window.MONSTER_CHUNK_103 = [{"name":"Thanatotic Titan","cr":22,"xp":614400,"alignment":"CE","size":"Colossal","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"true seeing"}],"ac":38,"ac_touch":2,"ac_flat_footed":38,"ac_mods":"+12 armor, +24 natural, -8 size","hp":471,"hd":"23d10+345","hdvalue":23,"fort":22,"ref":15,"will":2,"save_mods":"+8 vs. mind-affecting","dr":"15/lawful and epic","immunities":["aging","death effects","disease"],"sr":33,"speed":[{"type":"land","speed":40,"special":"60 ft. without armor"}],"melee":"+3 unholy battleaxe +37 (6d6+22/19-20/x3), claw +29 (2d8+9) or 2 claws +34 (2d8+19)","ranged":"rock +16 (4d6+28)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"godslayer"},{"type":"rock-throwing","details":"100 ft."},{"type":"trample","details":"2d8+28, DC 40"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":35,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"mind blank"},{"spell":"spell turning"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"bestow curse"},{"spell":"break enchantment"},{"spell":"divination"},{"spell":"greater dispel magic"},{"spell":"sending"}]},{"frequency":"1/day","spells":[{"spell":"greater planar ally"},{"spell":"imprisonment"},{"spell":"meteor swarm"},{"spell":"true resurrection"}]},{"frequency":"3/day","spells":[{"spell":"disintegrate"},{"spell":"greater scrying"},{"spell":"heal"},{"spell":"mass suggestion"}]}],"strength":49,"dexterity":10,"constitution":41,"intelligence":27,"wisdom":20,"charisma":24,"baseatk":23,"cmb":6,"cmd":15,"feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":33},{"skill":"Craft (any one)","value":34},{"skill":"Diplomacy","value":30},{"skill":"Intimidate","value":30},{"skill":"Knowledge (arcana, history, and planes)","value":34},{"skill":"Knowledge (religion)","value":31},{"skill":"Perception","value":31},{"skill":"Perform (any one)","value":30},{"skill":"Sense Motive","value":31},{"skill":"Spellcraft","value":34},{"skill":"Stealth","value":5},{"skill":"Use Magic Device","value":33}],"languages":["Abyssal","Celestial","Common","telepathy 300 ft."],"sq":[{"type":"change shape","details":"any humanoid, alter self"}],"environments":["any (Abyss)"],"organizations":["solitary","pair","war band (3-6)"],"treasure":"standard (+3 full plate, +3 unholy battleaxe)","description_visual":"This titanic, armored figure wields an immense axe. Its hands end in claws, and its voice thunders with ruinous power.","group":"Thanatotic Titan","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Godslayer","kind":"Su","details":"When a thanatotic titan damages a creature capable of casting divine spells, that creature must make a DC 28 Will save or be unable to cast any divine spells for 1d4 rounds and be shaken. If the save is successful, the creature struck is merely shaken for 1 round. A thanatotic titan's attacks are treated as epic and evil for the purposes of overcoming damage reduction. The save DC is Charisma-based."}],"description":"Some believe that the titans were the first children of the gods-if this myth is true, then the fact that they waged war upon the gods becomes even more tragic. After they were betrayed to the gods by their own kin, the Thanatotic titans were banished into the Abyss. Today, they seethe with jealousy that their Elysian kin are allowed to wander the planes at will, while they can leave their Abyssal realm only by stealth. Now, these powerful outsiders spend much of their time brooding, fighting among themselves, and waging war for control of Abyssal realms against the legions of various demon lords.\n\nThanatotic titans see themselves as the true icons worthy of worship. Some work to found personal cults among mortals, while others simply wage unending crusades against the minions of the gods.","ecology":"","habitat_society":""},{"name":"Volnagur","cr":22,"xp":614400,"alignment":"CE","size":"Colossal","type":"magical beast","init":10,"senses":[{"type":"all-around vision"},{"type":"blindsense","modifier":"300 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"auras":["frightful presence (300 ft., DC 27)"],"ac":39,"ac_touch":9,"ac_flat_footed":32,"ac_mods":"+6 Dex, +1 dodge, +30 natural, -8 size","hp":437,"hd":"25d10+300","hdvalue":25,"hp_mods":["regeneration 30"],"fort":26,"ref":20,"will":12,"dr":"15/epic","immunities":["ability damage","acid","bleed","disease","electricity","energy drain","mind-affecting effects","paralysis","permanent wounds","petrification","poison","polymorph"],"sr":33,"speed":[{"type":"land","speed":20},{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"bite +29 (4d6+12), 3 razor tongues +29 (2d6+12/18-20/x3 plus 1d6 bleed, 1 Con bleed, and blood rage), 6 wings +24 (2d8+6)","ranged":"4 eye rays +23 (4d6 sonic/18-20 plus nausea)","space":"30 ft.","reach":"30 ft. (50 ft. with razor tongues)","spell_like_abilities_caster_level":25,"spell_like_abilities_concentration":37,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"acid fog"},{"spell":"greater invisibility"},{"spell":"song of discord"}]},{"frequency":"3/day","spells":[{"spell":"winds of vengeance"}]}],"strength":34,"dexterity":22,"constitution":35,"intelligence":7,"wisdom":14,"charisma":21,"baseatk":25,"cmb":45,"cmd":62,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (eye ray)"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Improved Precise Shot"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Snatch"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":19},{"skill":"Perception","value":20}],"languages":["Aklo"],"sq":[{"type":"hibernation"},{"type":"shatter silence"},{"type":"unstoppable force"}],"environments":["any (Casmaron)"],"organizations":["solitary"],"treasure":"none","description_visual":"This immense creature's warty body is shaped like a many-pointed star, and from it sprout nearly a dozen different wings.","group":"Spawn of Rovagug","source":"Inner Sea Bestiary","special_abilities":[{"type":"Blood Rage","kind":"Ex","details":"Any creature taking bleed damage from Volnagur's razor tongues takes a -4 penalty on Will saves and is affected as the murderous command spell (Will DC 16 negates) each round that bleeding continues, ignoring allies that are also taking bleed damage from Volnagur."},{"type":"Eye Rays","kind":"Su","details":"Volnagur fires eye rays at a range of up to 120 ft. Creatures struck by his eye rays are nauseated for 1 minute (Fortitude DC 29 negates). In addition, if the target fails a second Fortitude save against the same DC, it gains one of the following conditions, lasting as long as the nauseated condition, as its mind and body begin to unravel (roll 1d6): 1-confused, 2-fatigued (exhausted if already fatigued), 3-shaken (increase severity of fear effect if already present), 4-sickened, 5-staggered, 6-stunned. Reroll if an identical condition already exists. This is a sonic effect. The save DC is Charisma-based."},{"type":"Shatter Silence","kind":"Su","details":"Volnagur's presence unravels magical silence effects or effects that provide energy resistance against sonic attacks. At the beginning of its turn, any such effect within 60 ft. is targeted as dispel magic (caster level 25th)."}],"description":"Volnagur, the End-Singer, is an alien thing whose very presence brings turbulence, disturbance, and cacophony wherever he soars. He flits with effortless grace upon a hideous assortment of mismatched wings that constantly molt and rot from within, the oldest wings falling off as new ones spring up and grow in their place. His skirling cry awakens madness and blood fury in those who listen, as does the touch of his impossibly long, jagged-razor tongues. Alien harmonics induced by his grotesque gaze cripple those upon whom he gazes.","ecology":"","habitat_society":""},{"name":"Blood Queen","cr":23,"xp":819200,"alignment":"CE","size":"Gargantuan","type":"outsider","subtypes":["native"],"init":4,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"surrogate senses"}],"ac":38,"ac_touch":6,"ac_flat_footed":38,"ac_mods":"+32 natural, -4 size","hp":471,"hd":"23d10+345","hdvalue":23,"hp_mods":["regeneration 10 (good)"],"fort":28,"ref":9,"will":24,"dr":"15/epic and lawful","immunities":["disease","electricity","mind-affecting effects","poison","sonic"],"sr":34,"speed":[{"type":"land","speed":10}],"melee":"bite +29 (2d6+10), 5 stings +29 (2d6+10/19-20 plus 2d6 electricity), 6 tentacles +24 (2d8+5/19-20 plus grab)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"horrifying bellow"},{"type":"swallow whole","details":"15d6 acid damage, AC 26, 47 hp"},{"type":"unholy gestation"}],"spell_like_abilities_caster_level":23,"spell_like_abilities_concentration":38,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"mass suffocation"}]},{"frequency":"3/day","spells":[{"spell":"greater command"}]},{"frequency":"5/day","spells":[{"spell":"cacophonous call"},{"spell":"deeper darkness"},{"spell":"dispel good"},{"spell":"inflict critical wounds"}]}],"strength":30,"dexterity":11,"constitution":40,"intelligence":20,"wisdom":29,"charisma":37,"baseatk":23,"cmb":37,"cmb_special":"+4 vs. grapple","cmd":47,"feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (sting)"},{"feat":"Improved Critical (tentacles)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":39},{"skill":"Diplomacy","value":39},{"skill":"Heal","value":32},{"skill":"Intimidate","value":39},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (history)","value":28},{"skill":"Knowledge (planes)","value":31},{"skill":"Knowledge (religion)","value":31},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":39},{"skill":"Spellcraft","value":31}],"languages":["Abyssal","Aklo","Common","Draconic","Kuru","Undercommon","telepathy 100 ft."],"sq":[{"type":"blood link"}],"environments":["any"],"organizations":["solitary"],"treasure":"triple","description_visual":"This hideous monstrosity looks like an enormous curled maggot, varicolored like deeply bruised flesh. Three flailing tentacles adorn each side of the thing's huge, pulsating mouth, and five more arch from its hindquarters.","source":"Isles Of The Shackles","special_abilities":[{"type":"Blood Link","kind":"Su","details":"Three times per day as a standard action, the Blood Queen may psychically link to up to 23 Hit Dice of kuru within 100 ft. of either itself or one of its kuru surrogates; it may choose which specific kuru it would like to affect with this ability, but HD that are not sufficient to affect a creature are wasted. Any kuru linked to in this way must succeed at a DC 28 Will save or be forced to carry out the Blood Queen's telepathic commands to the best of its ability. In addition, a linked kuru gains a +4 morale bonus to Strength and Constitution and is immune to mind-affecting effects. The blood link lasts for 1 minute or until the Blood Queen ends the effect (a free action). When the blood link is broken, the affected kuru takes 1 point of Intelligence damage and cannot be linked to again for 24 hours. The save DC is Charisma-based."},{"type":"Horrifying Bellow","kind":"Su","details":"Three times per day as a standard action, the Blood Queen can release a terrifying bellow that affects a 30-foot-radius spread. Any creature within the affected area must succeed at a DC 34 Will save or be paralyzed for 1d4 rounds. The save DC is Charisma-based."},{"type":"Surrogate Senses","kind":"Su","details":"In addition to its blindsight, the Blood Queen can constantly see and hear through its unholy kuru surrogates as though with a permanent clairaudience/ clairvoyance spell. If at any time one of the Blood Queen's surrogates is killed, it is dazed for 1 round."},{"type":"Unholy Gestation","kind":"Ex","details":"Whenever the Blood Queen swallows an unconscious humanoid or renders a humanoid unconscious with its swallow whole ability, it moves the victim through its digestive track, where the victim no longer takes damage, but rather begins to gestate within the Blood Queen's transformative stomach for 1d4 rounds. After the creature has finished gestating, it is regurgitated from the hindquarters of the Blood Queen, encased in an opaque mucous pod. Any attempt to remove a gestated humanoid from its pod causes massive system shock, and the humanoid takes 6d6 points of damage unless it succeeds at a DC 25 Fortitude save or those releasing it succeed at a DC 25 Heal check. As a swift action, the Blood Queen can send strong telepathic emanations to any pod within 100 ft., causing it to violently explode. The resulting spray of bilious ooze deals 6d6 points of acid damage to the creature encased in the pod and to any creatures in a 15-foot-radius burst. Alternatively, the Blood Queen may allow an encased humanoid to continue to gestate for at least 24 hours, and after that duration may release the fully metamorphosed creature from its pod at any point. When released, the victim completes its transformation into a kuru surrogate (see the Kuru Surrogate section below). The Blood Queen may create any number of pods, but can only possess up to six kuru surrogates at any one time (if the Blood Queen releases a seventh kuru surrogate from its mucus pod, the oldest surrogate immediately dies no matter where it is and the Blood Queen is dazed for 1 round). The save DCs are Constitution-based."}],"description":"Millennia ago, when the repugnant cyclops empire of Ghol-Gan populated the Shackles, its foul and alien gods sent powerful servants from beyond to act as their intermediaries, guiding and corrupting the empire until its ignominious collapse, at which point the gods and their minions fled Golarion altogether. However, one of these vile servants remained even after Ghol-Gan's collapse, a wretched horror known as the Blood Queen. It has dwelt for centuries in its foul subterranean chamber in a ruined Ghol-Gan temple called Ganagsau in the Cannibal Isles, and it was this blasphemous being who transformed the kuru into the degenerate race they are today, convincing them that it is a living goddess worthy of their veneration. The Blood Queen has a kuru high priest who goes by the name Bukrugsor, and this devoted thrall sees to it that his dark patron is brought regular sacrificial victims and offerings of blood.\n\nThe Blood Queen has no eyes, per se-rather, what look like angry pustules all over its bloated body act as sensory organs. In addition, it is able to see and hear the world through the various kuru surrogates its followers have interspersed throughout the Cannibal Isles. Its grotesque mouth is capable of articulating a number of languages, though if it deigns to speak with a creature it usually does so via its telepathy. While the Blood Queen uses the short tentacles that extend from its mouth to devour prey and sacrificial offerings, the tentacles that emanate from its hindquarters are long, muscular, and tipped with bonelike stingers that allow it to manipulate objects and electrify victims.\n\nThe Blood Queen is nearly immobile, being a massive, swollen beast that sits in the middle of a huge underground temple chamber in its ruined cathedral. While it may slowly undulate its bulk in one direction or another, in the years since its appearance on Golarion, the Blood Queen has grown far too large to fit through any of the limestone chamber's exits. Only the Blood Queen's high priest, those destined to become surrogate kuru, or sacrifices to the behemoth monster are allowed within this foul throne room. Sometimes unwilling sacrifices are dropped into the chamber from a hole in the ceiling and the exits are sealed so that the Blood Queen may toy with its food before it feeds. A being of monumental evil, the Blood Queen expresses its rage at its divine abandonment by spreading as much pain and havoc as it can. Whether it ever escapes its ancient, self-made prison remains to be seen, though all right-thinking creatures that know of its existence shudder at the prospect.\n\nKuru Surrogates The Blood Queen's favored deacons are known as kuru surrogates, and such monstrosities are created when the horror digests a creature and entombs the victim in one of its paralytic sacs for long enough. The creature that emerges is essentially brain-dead, having been completely stripped of its wits and nervous system. A kuru surrogate remains in its vegetative state until it starves, is killed, or is affected by a heal spell or a similar effect of equal or greater power. Kuru surrogates are revered among the Blood Queen's devout, who transport the immobile things around the Cannibal Isles, perpetually caring for the \"blessed\" individuals. The Blood Queen acts through these surrogates and uses them to augment and command its kuru followers, linking with its minions in order to capture any who oppose it or its wicked cult of cannibals.","ecology":"","habitat_society":""},{"name":"Chemnosit","cr":23,"xp":819200,"alignment":"CE","size":"Colossal","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"180 ft."}],"auras":["frightful presence (300 ft., DC 26)"],"ac":39,"ac_touch":3,"ac_flat_footed":38,"ac_mods":"+1 Dex, +36 natural, -8 size","hp":472,"hd":"27d10+324","hdvalue":27,"hp_mods":["regeneration 30"],"fort":29,"ref":18,"will":13,"dr":"15/epic","immunities":["ability damage","acid","bleed","cold","disease","energy drain","mind-affecting effects","paralysis","permanent wounds","petrification","poison","polymorph"],"sr":34,"speed":[{"type":"land","speed":40},{"type":"burrow","speed":40}],"melee":"6 toothed tentacles +33 (2d10+13/19-20 plus grab)","ranged":"ray +20 (disintegrate/19-20)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"hungry gaze"},{"type":"spines"},{"type":"swallow whole","details":"2d10+13 plus 1d4 Str damage, AC 28, 47 hp"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":39,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"disintegrate"}]},{"frequency":"1/day","spells":[{"spell":"earthquake"}]}],"strength":36,"dexterity":13,"constitution":34,"intelligence":5,"wisdom":14,"charisma":21,"baseatk":27,"cmb":48,"cmb_special":"+4 vs. grapple, +20 vs. overrun","cmd":59,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (hungry gaze)"},{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Blind-Fight"},{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (ray)"},{"feat":"Improved Critical (toothed tentacle)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (toothed tentacle)"}],"skills":[{"skill":"Climb","value":20},{"skill":"Perception","value":27},{"skill":"Swim","value":17}],"languages":["Aklo"],"sq":[{"type":"hibernation"},{"type":"unstoppable force"}],"environments":["any (Darklands)"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive beast possesses a mouth of rasping teeth and tentacles with biting mouths. In the center of its maw rests a glowing evil eye.","group":"Spawn of Rovagug","source":"Inner Sea Bestiary","special_abilities":[{"type":"Hungry Gaze","kind":"Su","details":"Chemnosit's gaze attack deals 3d6 points of nonlethal damage plus fatigue at a distance of 120 ft. A successful DC 30 Fortitude save negates the fatigue. Creatures already fatigued become exhausted; creatures already exhausted become staggered. A creature that fails its save must succeed at a DC 30 Will save or gain an overwhelming compulsion to eat flesh of creatures of its type, including its own if no other is available. The save DCs are Charisma-based."},{"type":"Spines","kind":"Ex","details":"Creatures striking Chemnosit with natural weapons, unarmed strikes, melee weapons, or melee touch attacks take 2d6+12 points of damage."}],"description":"The dread burrower Chemnosit is an engine of destruction, able to devour the stoutest construction and the mightiest of mortals with ease. His power lies in the profane glamour of his glowing eye, inspiring a gruesome urge to devour-a hunger for the flesh of one's own kind. For all his power, this is the true dread of the Monarch Worm. While he burrows constantly through the Darklands to the deepest Vaults of Orv, he sometimes rises to Golarion's surface bringing annihilation in his wake, as those corrupted by his awful eye wreak devastation upon themselves and their own people. Chemnosit drinks in the carnage like a feast before devouring any survivors.","ecology":"","habitat_society":""},{"name":"Elohim","cr":23,"xp":819200,"alignment":"N","size":"Huge","type":"outsider","subtypes":["extraplanar","mythic"],"init":16,"init_special":"mythic, dual initiative","senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"deathwatch"},{"type":"low-light vision"},{"type":"scent"}],"ac":39,"ac_touch":20,"ac_flat_footed":32,"ac_mods":"+6 Dex, +1 dodge, +5 insight, +19 natural, -2 size","hp":423,"hd":"22d10+302","hdvalue":22,"hp_mods":["regeneration 15 (epic weapons)"],"fort":26,"ref":13,"will":24,"defensive_abilities":["fortification (50%)"],"dr":"15/epic","immunities":["electricity"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":34,"speed":[{"type":"land","speed":60},{"type":"fly","speed":60,"maneuverability":"good"},{"type":"swim","speed":30}],"melee":"2 claws +27 (2d8+7), 8 tentacles +22 (2d8+3 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. cone, 20d8 electricity, Reflex DC 32 half, usable every 1d4 rounds"},{"type":"constrict","details":"2d8+10"},{"type":"mythic magic"},{"type":"mythic power","details":"6/day, surge +1d8"}],"spell_like_abilities_caster_level":23,"spell_like_abilities_concentration":38,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"deathwatch"},{"spell":"mind blank"},{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"baleful polymorph"},{"spell":"charm monster"},{"spell":"etherealness"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"rest eternal"},{"spell":"shapechange"},{"spell":"stone shape"}]},{"frequency":"1/day","spells":[{"spell":"create demiplane"},{"spell":"mage's disjunction"}]},{"frequency":"3/day","spells":[{"spell":"circle of death"},{"spell":"disintegrate"},{"spell":"power word stun"}]},{"frequency":"5/day","spells":[{"spell":"control weather"},{"spell":"greater dispel magic"},{"spell":"greater polymorph"},{"spell":"heal"},{"spell":"plane shift"},{"spell":"terraform"}]}],"strength":24,"dexterity":22,"constitution":32,"intelligence":25,"wisdom":29,"charisma":25,"baseatk":22,"cmb":31,"cmb_special":"+4 vs. grapple","cmd":53,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude","type":"mythic"},{"feat":"Greater Vital Strike"},{"feat":"Improved Great Fortitude"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will","type":"mythic"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":32},{"skill":"Heal","value":31},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana, dungeoneering, geography, nature, planes)","value":32},{"skill":"Perception","value":34},{"skill":"Sense Motive","value":34},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":23},{"skill":"Swim","value":15},{"skill":"Use Magic Device","value":29}],"languages":["speak with animals","telepathy 100 ft."],"sq":[{"type":"compression"},{"type":"create life"},{"type":"natural spellcasting"},{"type":"no breath"},{"type":"plantbringer"}],"environments":["any (extraplanar)"],"organizations":["solitary","horde (1 plus 5-20 animals, magical beasts, and plants of CR 8-10)"],"treasure":"double","description_visual":"This one-eyed being is a strange mix of insects, fungi, and other living things shaped into a single winged entity.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Create Life","kind":"Su","details":"At will, an elohim can create any one plant or living creature. A creature created can have no more than 4 Hit Dice and be no larger than Large size, and isn't under the elohim's control."},{"type":"Natural Spellcasting","kind":"Su","details":"An elohim can cast spells in any shape, similar to the Natural Spell feat."}],"description":"An elohim is a strange being obsessed with creating miniature worlds populated with creatures of its choosing. It creates new permanent demiplanes or alters remote environments in pre-existing planes, seeds them with new life, then eventually abandons them. An elohim might return to its creation decades or centuries later to observe how its progeny have fared, and might allow them to continue or eradicate them completely. Elohim communicate with other beings only rarely, and always in a cryptic fashion.","ecology":"","habitat_society":""},{"name":"Great Wyrm Gold Dragon","cr":23,"xp":819200,"alignment":"LG","size":"Colossal","type":"dragon","subtypes":["fire"],"init":-2,"senses":[{"type":"dragon senses"}],"auras":["fire (10 ft., 2d6 fire)","frightful presence (360 ft., DC 33)"],"ac":40,"ac_touch":0,"ac_flat_footed":40,"ac_mods":"-2 Dex, +40 natural, -8 size","hp":465,"hd":"30d12+270","hdvalue":30,"fort":26,"ref":15,"will":27,"dr":"20/magic","immunities":["fire","paralysis","sleep"],"sr":34,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":300,"maneuverability":"clumsy"},{"type":"swim","speed":60}],"melee":"bite +38 (4d8+24/19-20), 2 claws +38 (4d6+16/19-20), tail slap +36 (4d6+24/19-20), 2 wings +36 (2d8+8/19-20)","space":"30 ft.","reach":"20 ft. (30 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"70-ft. cone, 24d10 fire, DC 34"},{"type":"crush","details":"4d8+24, DC 34"},{"type":"tail sweep","details":"2d8+24, DC 34"},{"type":"weakening breath"}],"spell_like_abilities_caster_level":30,"spell_like_abilities_concentration":39,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"bless"},{"spell":"daylight"},{"spell":"detect evil"},{"spell":"foresight"},{"spell":"geas/quest"},{"spell":"sunburst"}]}],"spellsknown_caster_level":19,"spellsknown_concentration":28,"spellsknown":[{"spell_level":9,"spell_slots":4,"spells":[{"spell":"time stop"},{"spell":"wish"}]},{"spell_level":8,"spell_slots":7,"spells":[{"spell":"euphoric tranquility"},{"spell":"greater prying eyes"},{"spell":"protection from spells"}]},{"spell_level":7,"spell_slots":7,"spells":[{"spell":"greater teleport"},{"spell":"resurrection"},{"spell":"vision"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"antimagic field"},{"spell":"greater dispel magic"},{"spell":"heal"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"dispel evil"},{"spell":"plane shift"},{"spell":"teleport"},{"spell":"true seeing"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"divination"},{"spell":"restoration"},{"spell":"spell immunity"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"dispel magic"},{"spell":"haste"},{"spell":"invisibility purge"},{"spell":"prayer"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"aid"},{"spell":"cure moderate wounds"},{"spell":"lesser restoration"},{"spell":"resist energy"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"divine favor"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"stabilize"}]}],"strength":43,"dexterity":6,"constitution":29,"intelligence":26,"wisdom":27,"charisma":26,"baseatk":30,"cmb":54,"cmd":62,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Critical Focus"},{"feat":"Extend Spell"},{"feat":"Hover"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (wing)"},{"feat":"Improved Critical (tail)"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"},{"feat":"Wingover"}],"skills":[{"skill":"Diplomacy","value":41},{"skill":"Fly","value":15},{"skill":"Heal","value":41},{"skill":"Knowledge (arcana)","value":41},{"skill":"Knowledge (history)","value":41},{"skill":"Knowledge (local)","value":41},{"skill":"Knowledge (nobility)","value":41},{"skill":"Knowledge (planes)","value":41},{"skill":"Knowledge (religion)","value":41},{"skill":"Perception","value":45},{"skill":"Sense Motive","value":45},{"skill":"Spellcraft","value":41},{"skill":"Swim","value":57},{"skill":"Use Magic Device","value":41}],"languages":["Celestial","Common","Draconic","Elven","Halfling","4 more"],"sq":[{"type":"change shape"},{"type":"detect gems"},{"type":"divine aid"},{"type":"fast flight"},{"type":"luck"}],"environments":["warm plains"],"organizations":["solitary"],"treasure":"triple","description_visual":"Golden scales cover the body of this majestic dragon, and a regal crest of horns arches backward above wise and piercing eyes.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A very young or older gold dragon can assume any animal or humanoid form three times per day as if using polymorph."},{"type":"Detect Gems","kind":"Sp","details":"A young or older gold dragon can detect gems three times per day. This functions as locate object, but can only be used to locate gemstones."},{"type":"Divine Aid","kind":"Sp","details":"Once a week, a great wyrm gold dragon can call upon celestial powers for aid. This functions as a miracle."},{"type":"Fast Flight","kind":"Ex","details":"A young or older gold dragon is treated as one size category larger when determining his fly speed."},{"type":"Fire Aura","kind":"Su","details":"An old or older gold dragon is surrounded by an aura of fire. All creatures within 5 ft. of the dragon take 1d6 points of fire damage at the beginning of the dragon's turn. An ancient gold dragon's aura extends to 10 ft. A great wyrm's damage increases to 2d6. The dragon can activate or suppress this aura as a free action."},{"type":"Luck","kind":"Sp","details":"Once per day an adult or older gold dragon can touch a gem, usually one embedded in the dragon's hide, and enspell it to bring good luck. As long as the dragon carries the gem, it and every good creature within a given radius of it (10 ft. per age category) receives a +1 luck bonus on all saving throws. If the dragon gives an enspelled gem to another creature, only that bearer gets the bonus. The effect lasts 1d3 hours plus 3 hours per age category of the dragon. This ability is the equivalent of a 2nd-level spell."},{"type":"Weakening Breath","kind":"Su","details":"Instead of a cone of fire, a gold dragon can breathe a cone of weakening gas. Creatures within the cone must succeed on a Fortitude save or take 1 point of Strength damage per age category (Will save half)."}],"description":"Gold dragons are the epitome of virtue. Other metallic dragons revere their gold cousins as the agents of divine forces and the paragons of dragonkind, and often seek them for advice or aid.","ecology":"","habitat_society":""},{"name":"Ifestus","cr":23,"xp":819200,"alignment":"CE","size":"Colossal","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":39,"ac_touch":4,"ac_flat_footed":37,"ac_mods":"+9 armor, +2 Dex, +26 natural, -8 size","hp":471,"hd":"23d10+345","hdvalue":23,"fort":22,"ref":17,"will":18,"dr":"15/good and lawful","immunities":["aging","death effects","disease","fire"],"sr":34,"speed":[{"type":"land","speed":40,"special":"60 ft. without armor"}],"melee":"+3 anarchic warhammer +36 (6d6+21/x3) or 2 slams +33 (2d8+18)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"trample","details":"2d8+27, DC 39"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":35,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect thoughts"},{"spell":"spell turning"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"bestow curse"},{"spell":"break enchantment"},{"spell":"greater dispel magic"},{"spell":"sending"}]},{"frequency":"1/day","spells":[{"spell":"meteor swarm"},{"spell":"regenerate"},{"spell":"storm of vengeance"}]},{"frequency":"3/day","spells":[{"spell":"earthquake"},{"spell":"greater scrying"},{"spell":"heal"},{"spell":"mass suggestion"}]}],"strength":47,"dexterity":14,"constitution":40,"intelligence":19,"wisdom":21,"charisma":24,"baseatk":23,"cmb":49,"cmb_special":"+2 vs. sunder","cmd":61,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Craft (any)","value":23},{"skill":"Diplomacy","value":21},{"skill":"Disable Device","value":20},{"skill":"Intimidate","value":33},{"skill":"Knowledge (engineering)","value":24},{"skill":"Knowledge (geography)","value":20},{"skill":"Knowledge (planes)","value":25},{"skill":"Perception","value":31},{"skill":"Sense Motive","value":28},{"skill":"Survival","value":25},{"skill":"Swim","value":30},{"skill":"Use Magic Device","value":30}],"languages":["Abyssal","Celestial","Common","telepathy 300 ft."],"environments":["any"],"organizations":["unique"],"treasure":"none","source":"AP 60","special_abilities":[{"type":"Stasis","kind":"Su","details":"Ifestus can merge with the earth, typically under a volcano or near a magma vent or tectonic plate, and go dormant for an indeterminate amount of time. The titan doesn't have to breathe, eat, or drink during this time. He is aware of his immediate surroundings out to the range of his telepathy during this time, and may communicate with creatures within the range of his telepathy. Ifestus can end his stasis at any time as a free action. Entering status is a standard action."}],"description":"Ifestus found his way to Golarion thousands of years ago. He separates his time between catastrophic destruction and millennia-long slumbers in the molten bowels of the planet. A patient being, he uses his special ability to seek solitude in magma chambers, in massive volcanoes, and along the edges of grinding tectonic plates. It's rumored that many of Golarion's greatest earthquakes and volcanic eruptions were either facilitated by or witnessed by Ifestus. He was slumbering in a great volcano in Casmaron when Earthfall struck, and wandered the surface of the planet for a decade thereafter before finally settling into Mount Keeba. Quiet for thousands of years, Ifestus now rumbles and stirs.","ecology":"","habitat_society":"","gear":"+3 breastplate, +3 anarchic warhammer"},{"name":"Jabberwock","cr":23,"xp":819200,"alignment":"CE","size":"Huge","type":"dragon","subtypes":["air","fire"],"init":5,"senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"true seeing"}],"auras":["frightful presence (120 ft., DC 31)"],"ac":40,"ac_touch":14,"ac_flat_footed":34,"ac_mods":"+5 Dex, +1 dodge, +26 natural, -2 size","hp":455,"hd":"26d12+286","hdvalue":26,"hp_mods":["fast healing 15"],"fort":26,"ref":20,"will":24,"dr":"15/vorpal","immunities":["fire","paralysis","sleep"],"resists":[{"type":"acid","value":30},{"type":"electricity","value":30},{"type":"sonic","value":30}],"sr":31,"weaknesses":["fear of vorpal weapons","vulnerable to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":80,"maneuverability":"poor"}],"melee":"bite +37 (4d8+19/19-20/x3), 2 claws +37 (3d6+13/19-20 plus grab), tail slap +32 (2d8+19), 2 wings +32 (1d8+6)","ranged":"2 eye rays +29 touch (15d6 fire/19-20 plus burn)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"burble"},{"type":"burn","details":"6d6, DC 34"},{"type":"eye rays"},{"type":"whiffling"}],"strength":37,"dexterity":20,"constitution":33,"intelligence":12,"wisdom":29,"charisma":26,"baseatk":26,"cmb":41,"cmb_special":"+4 vs. grapple","cmd":57,"feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Critical (eye rays)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":31,"special":"+35 jump"},{"skill":"Escape Artist","value":31},{"skill":"Fly","value":26},{"skill":"Intimidate","value":37},{"skill":"Knowledge (nature)","value":30},{"skill":"Perception","value":38},{"skill":"Sense Motive","value":38}],"languages":["Aklo","Common","Draconic","Gnome","Sylvan"],"sq":[{"type":"planar acclimation"}],"environments":["any forests"],"organizations":["solitary"],"treasure":"triple","description_visual":"This dragon has a long neck and terrible claws. The beast shrieks and babbles, thrashing its tail and wings in a violent manner.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Burble","kind":"Su","details":"A jabberwock can burble once every 1d4 rounds as a standard action. This blast of strange noises and shouted nonsense in the various languages known to the jabberwock (and invariably some languages it doesn't know) affects all creatures within a 60-foot-radius spread-these creatures must make a DC 31 Will save or become confused for 1d4 rounds. Alternatively, the jabberwock can focus its burble attack to create a 60- foot line of sonic energy that deals 20d6 points of sonic damage (DC 31 Reflex save for half). The confusion effect is mind-affecting; both are sonic effects. The save DC is Charisma-based."},{"type":"Damage Reduction","kind":"Ex","details":"A jabberwock's damage reduction can be bypassed only by weapons that possess the vorpal weapon enhancement."},{"type":"Eye Rays","kind":"Su","details":"The jabberwock can project beams of fire from its eyes as a ranged touch attack as a standard action, with a range increment of 60 ft. It projects two beams, and can target different creatures with these beams if it wishes as long as both targets are within 30 ft. of each other. A creature that takes damage from an eye beam suffers burn."},{"type":"Fear of Vorpal Weapons","kind":"Ex","details":"A jabberwock knows that a vorpal weapon can kill it swiftly. As soon as it takes damage from a vorpal weapon, a jabberwock becomes shaken for 1 round. If it is hit by a critical threat from a vorpal weapon, whether or not the critical hit is confirmed, the jabberwock is staggered for 1 round."},{"type":"Planar Acclimation","kind":"Ex","details":"A jabberwock is always considered to be on its home plane, regardless of what plane it finds itself upon. It never gains the extraplanar subtype."},{"type":"Whiffling","kind":"Ex","details":"A jabberwock's wings and violent motions create a significant amount of wind whenever it makes a full attack action. These winds surround the monster to a radius of 30 ft., and are treated as severe winds-ranged attacks take a -4 penalty when targeting a jabberwock while it is whiffling, and Medium creatures must make a DC 10 Strength check to approach the creature. Small or smaller creatures in this area that fail a DC 15 Strength check are blown away."}],"description":"The jabberwock is a true creature of legend-a subject of poetry, song, and myth in many cultures. It is known to be a devastating creature in combat whose arrival presages times of ruin and violence; these stories also tell of the creature's fear of the tools some say were created in ancient times for the sole purpose of defeating them—vorpal weapons. A jabberwock is 35 ft. tall and weighs 8,000 pounds.\n\nthe Tane are presented in this book-the sard and the thrasfyr. None of the Tane are lower than CR 16 in power and all possess the planar acclimation special quality, but beyond that, they generally share no specific abilities or characteristics save for their common source in the primal world.\n\nWhen a jabberwock comes to the Material Plane, it does so to spread destruction and ruin. Typically, the monster seeks out a remote forest lair at least a day's flight from civilization, then emerges from this den once a week to seek out a new place to destroy. It has no true interest in amassing treasure, but often gathers objects of obvious value to bring back to its den in order to encourage heroes to seek it out-to a jabberwock, it makes no difference whether it seeks out things to destroy or lets those things come to it.\n\nJabberwocks age, eat, drink, and sleep like any living creature, but they don't reproduce in the classic sense of the word. The creation of a new jabberwock-or of any of the Tane, in fact-is regulated by the strange and unknowable godlike entities that dwell in the primeval world. These fey lords create new jabberwocks as they are needed-sometimes varying the exact particulars (see Variant Jabberwocks, below), but always creating a fully formed adult creature. No young jabberwock has ever been encountered as a result.\n\nThe strange vulnerability a jabberwock possesses against vorpal weapons has long been a matter of intrigue and speculation among scholars. Most believe that, once upon a time, only one jabberwock existed, a creature of such great power that nothing could hurt it. Nothing, that is, save for a legendary sword forged for a mortal hero by a now-forgotten artisan or god. So epic was this battle that it created strange echoes throughout reality, and as a result, these echoes, in the form of the vorpal swords and jabberwocks known today, can be found on many worlds.\n\nVARIANT JABBERWOCKS\n\nThe notion of a \"lesser\" jabberwock is something of a misnomer, for even these creatures are powerful foes. A lesser jabberwock is generally a CR 20 version of the typical jabberwock-you can achieve a creature of this power by lowering the typical jabberwock's Hit Dice by 3 and by reducing its ability scores by 4 points each. Alternatively, you can apply the young creature simple template, but bear in mind that such a monster isn't technically any younger than a typical jabberwock.\n\nAs creatures from the primal world of the fey, some jabberwocks are as varied as the strange terrains and\n\nThe jabberwock isn't a creature of the Material Plane, but one from the primal world of the fey. It comes from a region of reality where life is more robust, where emotions are more potent, and where dreams and nightmares can come alive. Even in such incredible realms, though, the jabberwock is a creature to be feared. It belongs to a category of powerful creatures whose shapes and types run the gamut of possibility-a group known collectively as the \"Tane.\" Of the Tane, the jabberwock is said to be the most powerful, but the others in this grouping are far from helpless. Said to have been created as goliaths of war and madness, dreamt and stitched into being by the strange gods of this primeval reality, the Tane are as mysterious as they are powerful. Two other creatures of realms in that primal world, as if these environs have more to do with their manifestation than most scholars suspect. Generally, these changes simply alter the type of damage a jabberwock's eye beams deal and the types of energy it is immune to. A jabberwock from a primeval glacial world would possess eye beams that deal cold damage, while a jabberwock from a storm-lashed world would deal electricity damage with its eye beams. If the nature of a jabberwock's eye beams change, its burn ability changes to match, and it replaces its immunity to fire with immunity to the new energy type (while gaining resist fire 30 in place of the lost immunity to fire).","ecology":"","habitat_society":""},{"name":"Solar","cr":23,"xp":819200,"alignment":"NG","size":"Large","type":"outsider","subtypes":["angel","extraplanar","good"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"detect evil"},{"type":"detect snares and pits"},{"type":"true seeing"}],"auras":["protective aura"],"ac":44,"ac_touch":11,"ac_flat_footed":42,"ac_mods":"+14 armor, +1 Dex, +1 dodge, +19 natural, -1 size | +4 deflection vs. evil","hp":363,"hd":"22d10+242","hdvalue":22,"hp_mods":["regeneration 15 (evil artifacts, effects, and spells)"],"fort":25,"ref":14,"will":23,"save_mods":"+4 vs. poison, +4 vs. evil","dr":"15/epic and evil","immunities":["acid","cold","petrification"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":34,"speed":[{"type":"land","speed":35,"special":"50 ft. without armor"},{"type":"fly","speed":100,"special":"150 ft. without armor","maneuverability":"perfect"}],"melee":"+5 dancing greatsword +35 (3d6+18) or slam +30 (2d8+13)","ranged":"+5 composite longbow (+9 Str bonus) +31 (2d6+14 plus slaying arrow)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":30,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect snares and pits"},{"spell":"discern lies"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"animate objects"},{"spell":"commune"},{"spell":"continual flame"},{"spell":"dimensional anchor"},{"spell":"greater dispel magic"},{"spell":"holy smite"},{"spell":"imprisonment"},{"spell":"invisibility","details":"self only"},{"spell":"lesser restoration"},{"spell":"remove curse"},{"spell":"remove disease"},{"spell":"remove fear"},{"spell":"resist energy"},{"spell":"speak with dead"},{"spell":"summon monster VII"},{"spell":"waves of fatigue"}]},{"frequency":"1/day","spells":[{"spell":"greater restoration"},{"spell":"power word blind"},{"spell":"power word kill"},{"spell":"power word stun"},{"spell":"prismatic spray"},{"spell":"wish"}]},{"frequency":"3/day","spells":[{"spell":"blade barrier"},{"spell":"earthquake"},{"spell":"heal"},{"spell":"mass charm monster"},{"spell":"permanency"},{"spell":"resurrection"},{"spell":"waves of exhaustion"}]}],"spellsprepared_caster_level":20,"spellsprepared_concentration":30,"spellsprepared":[{"spell_level":9,"spell_slots":1,"spells":[{"spell":"etherealness"},{"spell":"mass heal"},{"spell":"miracle"},{"spell":"storm of vengeance"}]},{"spell_level":8,"spell_slots":1,"spells":[{"spell":"fire storm"},{"spell":"holy aura","count":2},{"spell":"mass cure critical wounds","count":2}]},{"spell_level":7,"spell_slots":1,"spells":[{"spell":"destruction"},{"spell":"dictum"},{"spell":"ethereal jaunt"},{"spell":"holy word"},{"spell":"regenerate"}]},{"spell_level":6,"spell_slots":1,"spells":[{"spell":"banishment"},{"spell":"heroes' feast"},{"spell":"mass cure moderate wounds"},{"spell":"undeath to death"},{"spell":"word of recall"}]},{"spell_level":5,"spell_slots":1,"spells":[{"spell":"break enchantment"},{"spell":"breath of life"},{"spell":"dispel evil"},{"spell":"plane shift"},{"spell":"righteous might"},{"spell":"symbol of sleep"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"cure critical wounds","count":3},{"spell":"death ward"},{"spell":"dismissal"},{"spell":"neutralize poison","count":2}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"cure serious wounds"},{"spell":"daylight"},{"spell":"invisibility purge"},{"spell":"magic circle against evil"},{"spell":"prayer"},{"spell":"protection from energy"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"align weapon"},{"spell":"bear's endurance"},{"spell":"bull's strength"},{"spell":"consecrate"},{"spell":"cure moderate wounds","count":2},{"spell":"eagle's splendor"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"bless"},{"spell":"cure light wounds","count":3},{"spell":"divine favor"},{"spell":"entropic shield"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"purify food and drink"},{"spell":"stabilize"},{"spell":"virtue"}]}],"strength":28,"dexterity":20,"constitution":30,"intelligence":23,"wisdom":27,"charisma":25,"baseatk":22,"cmb":32,"cmd":47,"feats":[{"feat":"Cleave"},{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (any one)","value":31},{"skill":"Diplomacy","value":32},{"skill":"Fly","value":32},{"skill":"Knowledge (history)","value":31},{"skill":"Knowledge (nature)","value":31},{"skill":"Knowledge (planes)","value":31},{"skill":"Knowledge (religion)","value":31},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":33},{"skill":"Spellcraft","value":31},{"skill":"Stealth","value":21},{"skill":"Survival","value":31}],"languages":["Celestial","Draconic","Infernal","truespeech"],"sq":[{"type":"change shape","details":"alter self"}],"environments":["any good-aligned plane"],"organizations":["solitary","pair"],"treasure":"double (+5 full plate, +5 dancing greatsword, +5 composite longbow [+9 Str bonus])","description_visual":"This towering humanoid creature has shining topaz eyes, metallic skin, and three pairs of white wings.","group":"Angel","source":"PFRPG Bestiary","special_abilities":[{"type":"Spells","details":"Solars can cast divine spells as 20th-level clerics. They don't gain access to domains or other cleric abilities."},{"type":"Slaying Arrow","kind":"Su","details":"A solar's bow needs no ammunition, and automatically creates a slaying arrow of the solar's choice when drawn."}],"description":"Solars are the greatest type of angel, usually serving at the right hand of a deity or championing a cause that benefits an entire world or plane. A typical solar looks roughly human, though some physically resemble other humanoid races and a rare few have even more unusual forms. A solar stands about 9 ft. tall and weighs about 500 pounds, with a strong, commanding voice that is impossible to ignore. Most have silvery or golden skin. Blessed with an array of magical powers and the spellcasting abilities of the most powerful clerics, solars are powerful opponents capable of single-handedly slaying mighty evils. They are the greatest trackers among the celestials, the most masterful of which are said to be able to track the days-old wake of a pit fiend flying through the Astral Plane. Some take on the mantle of monster-slayers and hunt powerful fiends and undead such as devourers, night hags, night shades, and pit fiends, even making forays into the evil planes and the Negative Energy Plane to destroy these creatures at their source before they can bring harm to mortals. A few very old solars have succeeded at this task and bear slayer-names of dread creatures that are now extinct by the solar's hand. Solars accept roles as guardians, usually of fundamental supernatural concepts, or objects or creatures of great importance. On one world, a group of solars patrols the energy conduits of the sun, alert for any attempts by evil races such as drow to snuff out the light and bring eternal darkness. On another, seven solars stand watch over seven mystical chains keeping evil gods bound within a prison demiplane. On yet another, a solar with a flaming sword stands watch over the original mortal paradise so that no creature may enter. In worlds where the gods cannot take physical form, they send solars to be their prophets and gurus (often pretending to be mortals), laying the foundation for cults that grow to become great religions. Likewise, in worlds oppressed by evil, solars are the secret priests who bring hope to the downtrodden, or in some cases allow themselves to be martyred so that their holy essence can explode outward to land and grow in the hearts of great heroes-to-be. Though they are not gods, the solars' power approaches that of demigods, and they often have an advisory role for younger or weaker deities. In some polytheistic faiths, mortals worship one or more solars as aspects or near-equal servants of the true deities-never without the deity's approval-or consider notable solars to be offspring, consorts, lovers, or spouses of true deities (which they may be, depending on the deity). Unlike other angels, most solars are created from an amalgam of good souls and raw divine energy to directly serve the gods, but an increasing number of these powerful angels have been \"promoted\" to their existence as solars from lesser creatures like planetars or devas. A few rare and powerful good souls ascend directly to the status of solar. The oldest solars predate mortality and are among the gods' first creations. These strange solars are paragons of their kind and have little direct interaction with mortals, focusing on the protection or destruction of abstract concepts such as gravity, dark matter, entropy, and primordial evil. Solars who spend a long time in the Material Plane, especially those in the guise of mortals, are sometimes the source of halfcelestial or aasimar bloodlines in mortal families, due either to romantic dalliances or simply the mortals' proximity to celestial energy. Actual offspring are rare, and when they occur, it is always a mortal mother that bears the child-while solars can appear as either sex, the gods have not granted them the capacity for pregnancy or motherhood. Indeed, this fundamental truth is often what drives a solar to seek out a mortal lover. Since begetting a child upon a mortal is generally frowned upon by other solars, a solar father rarely interacts directly with the fate of his lover or child, so as to avoid bringing shame upon himself or his responsibilities. Yet such solars still watch over their progeny from afar, and in times of peril, they might even be moved to intercede to aid one of their endangered children, albiet in subtle and mysterious ways. All angels respect the power and wisdom of solars, and though these mightiest of angels usually work alone, they sometimes command multiple armies led by planetars, acting as great field marshals for massive incursions against the legions of Hell or the hordes of the Abyss.","ecology":"","habitat_society":""},{"name":"Talmandor","cr":23,"xp":819200,"alignment":"NG","size":"Large","type":"outsider","subtypes":["agathion","extraplanar","good"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"},{"type":"true seeing"}],"auras":["frightful presence (60 ft., DC 30)","protective aura (30 ft., DC 30, 10 rounds)","quell the profane"],"ac":40,"ac_touch":22,"ac_flat_footed":27,"ac_mods":"+13 Dex, +18 natural, -1 size","hp":472,"hd":"27d10+324","hdvalue":27,"fort":27,"ref":22,"will":0,"save_mods":"+4 vs. poison","defensive_abilities":["evasion"],"dr":"15/silver and evil","immunities":["electricity","petrification"],"resists":[{"type":"cold","value":10},{"type":"sonic","value":10}],"sr":34,"speed":[{"type":"land","speed":40},{"type":"fly","speed":180,"maneuverability":"good"}],"melee":"2 claws +40 (3d6+12/18-20/x3), 2 wings +37 (3d6+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"channel positive energy"},{"type":"coruscating charge"},{"type":"pounce"},{"type":"rend","details":"2 claws, 3d6+12"},{"type":"sacred slasher"},{"type":"twin talons"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":32,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"cloak of winds"},{"spell":"discern lies"},{"spell":"freedom of movement"},{"spell":"magic circle against evil"},{"spell":"mind blank"},{"spell":"see invisibility"},{"spell":"speak with animals"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"aid"},{"spell":"daylight"},{"spell":"dimension door"},{"spell":"dispel evil"},{"spell":"displacement","details":"self only"},{"spell":"greater command"},{"spell":"greater dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"hold monster"},{"spell":"magic missile"},{"spell":"remove fear"},{"spell":"river of wind"},{"spell":"wind wall"}]},{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"mass heal"},{"spell":"overwhelming presence"},{"spell":"summon","details":"level 8, 1d4+1 advanced avorals 100%"},{"spell":"sunburst"},{"spell":"whirlwind"}]},{"frequency":"3/day","spells":[{"spell":"break enchantment"},{"spell":"control winds"},{"spell":"divine power"},{"spell":"eagle aerie"},{"spell":"holy aura"},{"spell":"holy word"},{"spell":"miracle"},{"spell":"plane shift"},{"spell":"quickened empowered chain lightning"},{"spell":"spell turning"}]}],"strength":26,"dexterity":36,"constitution":35,"intelligence":19,"wisdom":23,"charisma":24,"baseatk":27,"cmb":2,"cmd":12,"feats":[{"feat":"Bleeding Critical"},{"feat":"Dimensional Agility"},{"feat":"Dimensional Assault"},{"feat":"Dimensional Dervish"},{"feat":"Critical Focus"},{"feat":"Empower Spell-Like Ability (chain lightning)"},{"feat":"Flyby Attack"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (chain lightning)"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":40},{"skill":"Bluff","value":20},{"skill":"Diplomacy","value":30},{"skill":"Fly","value":45},{"skill":"Handle Animal","value":30},{"skill":"Intimidate","value":30},{"skill":"Knowledge (history, local, nobility, planes)","value":10},{"skill":"Perception","value":44},{"skill":"Perform (oratory)","value":10},{"skill":"Sense Motive","value":36},{"skill":"Spellcraft","value":10},{"skill":"Stealth","value":38},{"skill":"Use Magic Device","value":34}],"languages":["Celestial","Common","Draconic","Infernal","speak with animals","truespeech"],"sq":[{"type":"benevolent mercy"},{"type":"lay on hands","details":"10d6, 10/day, as a 20th-level paladin"}],"environments":["any air (Nirvana)"],"organizations":["solitary","flight (Talmandor and 3-6 advanced avorals)"],"treasure":"triple","description_visual":"This gloriously plumed anthropomorphic eagle has feathers tipped with shimmering gold, and claws with sharp black talons.","source":"Andoran Birthplace Of Freedom","special_abilities":[{"type":"Benevolent Mercy","kind":"Su","details":"When Talmandor uses his lay on hands ability, he also removes all of the following conditions from the target: dazed, nauseated, paralyzed, poisoned, sickened, and stunned."},{"type":"Channel Positive Energy","kind":"Su","details":"Talmandor can expend two uses of his lay on hands ability to channel energy as a 20th-level cleric."},{"type":"Coruscating Charge","kind":"Su","details":"When Talmandor charges, he can transform his body into golden light. He becomes incorporeal until he arrives at the end of his charge and makes his physical attacks. In this form, he radiates light as a daylight spell. Any evil creature whose space he passes through is affected as by sunbeam (Reflex DC 35 negates and Reflex half), while good-aligned creatures whose space he passes through gain the benefit of good hope for 1d4 rounds. The save DC is Constitution-based."},{"type":"Protective Aura","kind":"Su","details":"Against attacks made or effects created by evil creatures, this ability provides a +4 deflection bonus to AC and a +4 resistance bonus on saving throws to anyone within 20 ft. of Talmandor. Otherwise, it functions as a magic circle against evil effect and a lesser globe of invulnerability, both with a radius of 20 ft. (and a caster level of 20th). The defensive benefits from the magic circle are not included in the statistics above."},{"type":"Quell the Profane","kind":"Su","details":"Talmandor's frightful presence aura affects only evil creatures. Evil creatures inside Talmandor's protective aura also become sickened, and profane bonuses are suppressed within his aura unless their caster level exceeds 20th."},{"type":"Sacred Slasher","kind":"Ex","details":"When attacking with his claws, Talmandor adds 1-1/2 times his Strength bonus on damage rolls. He also threatens a critical hit on a roll of 18-20 and multiplies critical hit damage by 3. His claws overcome all damage reduction of evil creatures."},{"type":"Twin Talons","kind":"Ex","details":"When using the attack action, Talmandor can attack a single target with both claws."}],"description":"Talmandor is the celestial patron of Andoran and a great leader of the avoral agathions, surpassed among their kind only by the empyreal lord Ylimancha, the Harborwing. Talmandor abides in the aptly named Soaring Palace of Talmandor the Golden on the plane of Nirvana, yet travels frequently among the planes. In addition to looking in on the nation that has arisen under his wings, he wanders the Outer Sphere, often acting as an ambassador between mortal priesthoods and the immortal servants of Erastil, Iomedae, and Shelyn.\n\nLike most agathions, Talmandor takes an interest in influencing mortals and bringing them to a place of enlightenment. He is convinced that the greatest enlightenment for mortals can be achieved through social interaction. He has observed that mortals respond best to a full, robust engagement with their fellow citizens, and that it's important to have a voice in the decision-making process of one's society. Talmandor sees hereditary aristocracy and primogeniture as shackles slowing society's ascent into a place of justice and peace where all citizens work together for the common good. Talmandor doesn't want the rights and importance of individuals to be sacrificed for the greater good, and advocates a balance between collective needs and communitarian works on the one hand and the individual's personal responsibilities and liberties on the other.\n\nAccording to popular legend, Talmandor developed his democratic theories and shared them with the mortal poet Darl Jubannich, who transcribed them in his now-famous treatise, On Government. However, while Talmandor favored overturning established structures of power where necessary, he never promoted anarchy and has long felt great sadness over how the core tenets of his political philosophy have been twisted beyond recognition in Galt. He strives to promote moderation and peaceful reconciliation within government, even in times of upheaval.\n\nIn some parts of Andoran, the adulation Talmandor has earned goes beyond respect to outright worship. The agathion steadfastly refuses to seek godhood in his own right, as he believes he can be a better inspiration to the goals of democratic freedom as a powerful outsider who can aid the mortal citizens of Andoran in times of great need, rather than becoming a godlike creature they worship from afar. Talmandor typically assists only those he feels have earned the right to call upon any ally of Andoran, though he is pleased to give advice to anyone if asked in earnest. He often appears to speak when called upon by the People's Council, offering what guidance he can, but never insists that his suggestions be enacted. He has been known to appear at the meetings of smaller city and town councils as well, though as a guest he doesn't speak until the council asks him to. Only if Andoran faced some threat it found impossible to handle on its own without his aid would Talmandor take direct action to protect the nation, though his regular presence is certainly considered carefully by Andoran's enemies.\n\nThough Andoran celebrates a feast day in his honor on 4 Erastus, Talmandor insists the celebration is held to honor him in his capacity as one of many heroes of the nation, rather than as its divine protector. Despite his refusal of the mantle of divinity, a few in Andoran (including a small but growing number of oracles and paladins) revere him as a nascent demigod embodying the virtues of hope, liberty, and community, and his worship has begun to grow in small congregations across the country.\n\nTalmandor is closely associated with birds of prey and as a result is the patron of the Steel Falcons order of the Eagle Knights of Andoran, as well as a frequent advisor to leaders within the order. Talmandor inspires their work as ambassadors of liberty, and he sometimes even sends aid to those in the midst of dangerous political missions aimed at cultivating peace. Those who rise to greatness also receive Talmandor's direct blessing, which he sees as a rightful reward for good works and a tool that allows those blessed to achieve even greater things. If called to serve through powerful magic (such as gate), Talmandor generally answers but refuses to grant direct assistance except to those overwhelmingly outmatched by evil foes. Even then, he generally requires any aid he gives be paid for in massive donations to the poor and oppressed, though he also often offers a free alternative to his direct involvement, such as receiving his blessing (often crafted with miracle) or gaining some insight into the caller's foes.","ecology":"","habitat_society":""},{"name":"Fafnheir","cr":24,"xp":1228800,"alignment":"CE","size":"Colossal","type":"dragon","init":14,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"true seeing"}],"ac":42,"ac_touch":12,"ac_flat_footed":32,"ac_mods":"+10 Dex, +30 natural, -8 size","hp":526,"hd":"27d12+351","hdvalue":27,"fort":28,"ref":25,"will":23,"defensive_abilities":["freedom of movement"],"dr":"20/cold iron and epic","immunities":["curse effects","dragon traits","electricity","fire","mind-affecting effects","paralysis","poison","sleep"],"sr":35,"speed":[{"type":"land","speed":50},{"type":"burrow","speed":30},{"type":"fly","speed":100,"maneuverability":"average"},{"type":"swim","speed":50}],"melee":"bite +36 (6d6+17/19-20 plus poison), 2 claws +36 (2d8+17/19-20), gore +36 (4d6+17/19-20), tail slap +31 (4d6+8 plus grab)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"breath weapon"},{"type":"constrict","details":"tail, 4d6+8"},{"type":"death curse"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":33,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"greater dispel magic"}]},{"frequency":"3/day","spells":[{"spell":"limited wish"},{"spell":"plane shift","details":"between First World and Material Plane only"},{"spell":"quickened greater dispel magic"},{"spell":"spell turning"},{"spell":"wall of force"}]}],"strength":45,"dexterity":30,"constitution":36,"intelligence":18,"wisdom":27,"charisma":29,"baseatk":27,"cmb":52,"cmb_special":"+4 vs. grapple","cmd":72,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Critical (gore)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (greater dispel magic)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":32},{"skill":"Intimidate","value":39},{"skill":"Knowledge (arcana)","value":34},{"skill":"Knowledge (geography)","value":34},{"skill":"Knowledge (history)","value":34},{"skill":"Knowledge (nature)","value":34},{"skill":"Perception","value":46},{"skill":"Stealth","value":24},{"skill":"Swim","value":55},{"skill":"Use Magic Device","value":39}],"languages":["Aklo","Common","Draconic","Skald","Sylvan"],"environments":["any (Grungir Forest)"],"organizations":["solitary"],"treasure":"triple","description_visual":"The scales of this craggy serpentine dragon are scarred and blackened. Its eyes flare with nightmarish power, and its mouth drips with liquid flame.","source":"Lands Of The Linnorm Kings","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds as a standard action, Fafnheir can breathe a 90-foot cone of burning wind, dealing 26d10 points of fire damage to all creatures in the area of effect. A DC 36 Reflex save halves the fire damage dealt. The save DC is Constitution-based. This wind has two additional effects as well. Deafening: Any creature in the area of effect that doesn't succeed at a DC 36 Fortitude save is deafened by the thunderous wind. Storm-Laced: The closest creature to Fafnheir in the area of effect is also blasted by a bolt of lightning and takes 20d6 points of electricity damage in addition to the fire damage dealt. This creature can make a second DC 36 Reflex save to halve this electricity damage. Tornado Force: The winds themselves gust at nearly 300 miles per hour, affecting all creatures in the area of effect as if they were caught in tornado-force winds. The wind lasts only a few moments during Fafnheir's action, so it has no real effect on ranged attacks, but it blows away any Large or smaller creature (or Huge or smaller flying creature) that fails a DC 15 Strength check."},{"type":"Death Curse","kind":"Su","details":"Fafnheir is a difficult creature to slay, especially since he lives on in the body of any creature that slays him. When a creature slays Fafnheir, it becomes afflicted by the Curse of Fafnheir. Curse of Fafnheir: save Will DC 32; effect creature's sense of self erodes as its personality is slowly replaced by Fafnheir's-this manifests as 1d6 points of Charisma drain every 24 hours. A target whose Charisma drops to 0 becomes comatose and must immediately make a DC 32 Fortitude save or die; every 24 hours that passes thereafter, the victim must make a new Fortitude save to avoid death (unless its Charisma score rises above 0, at which point it takes 1d6 points of Charisma drain). If a creature dies from the effects of this curse, its body explodes in a 60-foot burst of burning wind, with effects identical to Fafnheir's breath weapon. This effect occurs if the cursed victim dies from any effect, not just from the curse. One round later, Fafnheir gains the effect of a true resurrection spell, appearing at the same spot where the cursed victim died (or the closest area large enough to contain the Colossal creature), with full memories of the cursed victim's doings and accomplishments while cursed. The only way to permanently slay Fafnheir is to avoid becoming cursed after killing him, or to remove the curse before the victim dies. The effects of this curse end prematurely and immediately if Fafnheir is restored to life by other means. The save DC is Charisma-based."},{"type":"Freedom of Movement","kind":"Ex","details":"Fafnheir is under the constant effect of freedom of movement, as the spell of the same name. This effect cannot be dispelled."},{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 34; frequency 1/round for 10 rounds; effect 10d6 fire damage and 1d4 drain from each ability score; cure 3 consecutive saves. The save DC is Constitution-based."},{"type":"True Seeing","kind":"Ex","details":"Fafnheir has true seeing, as the spell of the same name. This effect cannot be dispelled."}],"description":"Called the Father of All Linnorms, Fafnheir is the oldest and mightiest of his kind to dwell upon Golarion-other, even more powerful linnorms exist on the First World, but on Golarion, Fafnheir is king. Crafty and powerful, Fafnheir is more than just a creature of rage or hunger, and is sometimes known to speak with those who come to him as supplicants for his wisdom. Tales say that to gain Fafnheir's advice, one must travel through Grungir Forest to the cavern entrance of the linnorm's lair, whereupon the supplicant must call into the opening several secret names for the ancient linnorm. A single step into the lair renders the supplication moot, for Fafnheir doesn't suffer intrusions. It is customary to bring a herd of sheep, oxen, or several thralls for him to feast upon.\n\nThose who find Fafnheir in a talkative mood and live to tell the tale report that the linnorm is well versed in numerous fields, and capable of working a wide range of magic through wishcrafting, though how much of his bragging is true is debatable. Fafnheir claims to have been the first linnorm to cross to Golarion from the First World after slaying three of that realm's Eldest, as well as to remember a time when the dragon god Dahak came to this world, and to have taken part in ancient battles against humanity as an ally of the serpentfolk. Certain Thassilonian accounts give support to his claim of providing advice and aid at times to Runelord Xanderghul, and he endured the Age of Darkness with ease. The past few thousand years have passed in the blink of an eye for the ancient linnorm, and he expects to survive for thousands more.\n\nFafnheir is aware of the prophecy that the hero who kills him will become king of all Ulfen. The linnorm also knows that in death he will be reborn from the burnt flesh of his slayer, and suggests to those who raise this topic with him that only by becoming him can such a Linnorm King rule. While Fafnheir has seen many challengers, few have offered him a true battle.\n\nFafnheir spends much of his time slumbering, but wakes quickly at the slightest deviation in the patterns of the world around him, and his dreaming mind touches the woods above and the blood of his children. Those who would come upon him unawares should not expect success unless they travel into his lair from other worlds, for his attunement to Grungir Forest is uncanny. The linnorm rarely ventures far from his lair, preferring to lure his enemies close and dispatch them on familiar ground. He loves nothing but his treasure, and cannot be bribed or threatened-the lure of potential treasure doesn't excite him nearly as much as what he already possesses. He is a subtle combatant, preferring to use trickery before launching into melee. Unlike his lesser kin, Fafnheir has a number of potent, if limited, spell-like abilities, and he often uses his limited wishes to great effect. He has long experience with direct confrontation, and his millennia of action have taught him tricks that few remember. He is one of the most deadly creatures in the Inner Sea region, and even the mightiest dragons fear his power.","ecology":"","habitat_society":""},{"name":"Festering Ulunat (The Unholy First)","cr":24,"xp":1228800,"alignment":"CE","size":"Colossal","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"600 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"600 ft."}],"auras":["frightful presence (300 ft., DC 30)"],"ac":42,"ac_touch":7,"ac_flat_footed":37,"ac_mods":"+5 Dex, +35 natural, -8 size","hp":525,"hd":"30d10+360","hdvalue":30,"hp_mods":["regeneration 30"],"fort":29,"ref":24,"will":22,"defensive_abilities":["regeneration"],"dr":"15/epic","immunities":["ability damage","bleed","disease","energy drain","fire","mind-affecting effects","paralysis","permanent wounds","petrification","poison","polymorph","sonic"],"sr":35,"speed":[{"type":"land","speed":60},{"type":"climb","speed":60},{"type":"fly","speed":90,"maneuverability":"poor"},{"type":"swim","speed":40}],"melee":"bite +36 (4d8+14/19-20 plus 6d6 acid), 4 claws +36 (4d6+14/19-20)","space":"60 ft.","reach":"60 ft.","special_attacks":[{"type":"crush"},{"type":"devour magic"},{"type":"disease"},{"type":"rend","details":"2 claws, 4d8+21"},{"type":"thunderous steps"},{"type":"trample","details":"4d8+21, DC 39"},{"type":"terrible claws"}],"strength":38,"dexterity":21,"constitution":35,"intelligence":3,"wisdom":30,"charisma":20,"baseatk":30,"cmb":52,"cmb_special":"+2 vs. bull rush, +4 vs. sunder","cmd":67,"cmd_special":"+2 vs. bull rush, +2 vs. sunder, +16 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Critical Focus"},{"feat":"Greater Sunder"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Sunder"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":26},{"skill":"Fly","value":8},{"skill":"Perception","value":30},{"skill":"Swim","value":22}],"languages":["Aklo (can't speak)"],"sq":[{"type":"hibernation"},{"type":"massive"},{"type":"no breath"}],"environments":["any (Sothis)"],"organizations":["unique"],"treasure":"none","group":"The Unholy First","source":"AP 84","special_abilities":[{"type":"Crush","kind":"Ex","details":"Ulunat uses its immense size as a formidable weapon. As a standard action, Ulunat can move over enemies or objects, using its whole body to crush them, dealing 20d6+30 points of damage. Crush attacks are effective only against opponents that are Huge or smaller. This attack affects as many creatures as fit in Ulunat's space. Creatures in the affected area must succeed at a DC 39 Reflex save or be pinned, automatically taking bludgeoning damage during the next round unless Ulunat moves off them. If Ulunat chooses to maintain the pin, it must succeed at a combat maneuver check as normal. Pinned foes take damage from the crush each round if they don't escape. The save DC is Strength-based."},{"type":"Devour Magic","kind":"Ex","details":"Ulunat has the ability to absorb magic directed at it and create arcane feedback that has the potential to shred a spellcaster's mind. Whenever Ulunat is targeted by a spell or spell-like ability, the caster must succeed at a DC 30 Will save or be affected as if he were targeted by phantasmal killer. If Ulunat is in the area of effect of a spell or spell-like ability, the caster must succeed at a DC 30 Will save or be affected as if he were targeted by insanity. The save DC is Charisma-based."},{"type":"Hibernation","kind":"Ex","details":"Ulunat can sleep for centuries and doesn't need to eat during these periods of dormancy, though it eats ravenously and almost constantly once it has been awakened. If Ulunat is forced into an inhospitable environment, it goes into hibernation until conditions are right for it to reawaken. While in hibernation, Ulunat's damage reduction improves to 50/epic and it gains immunity to any spell or spell-like ability that allows spell resistance as well as all divination effects."},{"type":"Massive","kind":"Ex","details":"Because of Ulunat's size, uneven ground and other terrain features that form difficult terrain generally pose no significant hindrance to its movement, though forests or settlements are considered difficult terrain. A Huge or smaller creature can move through any square Ulunat occupies, and vice versa. Ulunat can make attacks of opportunity only against foes that are Huge or larger, and can be flanked only by Huge or larger foes. Ulunat gains a bonus for being on higher ground only if its entire space is on higher ground than that of its target. It's possible for a Huge or smaller creature to climb Ulunat with a successful DC 30 Climb check, however unlike the normal rules regarding Ulunat and attacks of opportunity, a Small or larger creature that climbs on Ulunat provokes an attack of opportunity from the monster."},{"type":"Regeneration","kind":"Ex","details":"Like all Spawn of Rovagug, Ulunat is a nearly indestructible force. No form of attack can suppress Ulunat's regeneration-it regenerates even if disintegrated or slain by a death effect. If Ulunat fails a save against an effect that would kill it instantly, it rises from death 3 rounds later with 1 hit point if no further damage is dealt to its remains. It can be banished or otherwise transported as a means to save a region from devastation, but a method to kill Spawn of Rovagug like Ulunat has yet to be discovered."},{"type":"Terrible Claws","kind":"Ex","details":"Ulunat's natural weapons ignore all forms of damage reduction and hardness."},{"type":"Tremor Step","kind":"Ex","details":"Ulunat's thunderous steps shake the ground as it moves. While moving along the ground, any creatures within 100 ft. of Ulunat that are also in contact with the ground must succeed at a DC 39 Reflex save or be knocked prone as the beast thunders along. The save DC is Strength-based."}],"description":"The stories from the beginning of the First Age of Osirion claim that Azghaad killed Ulunat-some even say that he achieved this feat with the divine help of Nethys-but the truth is that the Spawn of Rovagug are unkillable. After a lengthy and dangerous battle, Azghaad banished Ulunat to a pocket realm beneath the place where its bloated shell still stands. In this realm, under the oldest and largest settlement in Osirion, Ulunat sleeps.\n\nBefore this ancient conf lict, the great beast emerged from the Pit of Gormuz and thundered across Golarion. As Ulunat neared what is now Sothis, cultists of Rovagug channeling the power of raw chaos in a massive ritual- chanting cacophonous praises to the Rough Beast—opened a direct link between Ulunat and Rovagug. Empowered by this divine connection, Ulunat grew to an immense size and charged across the land, trampling everything in its path.\n\nNow, thousands of years later, the Unholy First has begun to stir in its prison. Numerous past attempts to free the Unholy First have failed, and most of these were hidden from the public and Osirion's official history in hopes that the proper method for freeing Ulunat would remain unknown. However, this doesn't stop cultists and doomsayers from trying to bring back the terrible beast.\n\nBolstered by recently discovered information, a cult of Rovagug has created a key that they know can unlock Ulunat's prison. Using this key, they perform a ritual that breaks open Azghaad's prison and unleashes Festering Ulunat on Osirion once more. Fueled by their chaotic power and Rovagug's fury, the beast erupts from hibernation, destroying everything beneath the Black Dome. Once it reaches the bounds of its ancient carapace, it effectively molts, bursting fully formed from its old shell into Sothis.","ecology":"","habitat_society":""},{"name":"Guardian Dragon","cr":24,"xp":1228800,"alignment":"N","size":"Gargantuan","type":"dragon","subtypes":["aquatic","mythic"],"init":15,"init_special":"mythic","senses":[{"type":"blindsight","modifier":"120 ft."},{"type":"darkvision","modifier":"120 ft."},{"type":"detect magic"},{"type":"detect scrying"},{"type":"low-light vision"},{"type":"mistsight"}],"auras":["frightful presence (300 ft., DC 30)","security (1,000 ft.)"],"ac":44,"ac_touch":7,"ac_flat_footed":43,"ac_mods":"+6 armor, +1 Dex, +31 natural, -4 size","hp":529,"hd":"26d12+360","hdvalue":26,"fort":25,"ref":16,"will":24,"defensive_abilities":["fortification (50%)","poisonous blood (dragon bile)","unstoppable"],"dr":"15/epic and magic","immunities":["ability damage","ability drain","curses","death effects","dragon traits","sleep","paralysis","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"electricity","value":30},{"type":"fire","value":30},{"type":"sonic","value":30}],"sr":35,"speed":[{"type":"land","speed":50},{"type":"climb","speed":30},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":30}],"melee":"2 claws +36 (2d8+14), bite +36 (4d6+21 plus grab and poison), 2 wings +34 (2d6+7), tail slap +34 (2d8+21 plus grab)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"agonizing venom"},{"type":"breath weapon","details":"60-ft. cone, 2d4 Con damage from poison, Fortitude DC 33 half, usable every 1d4 rounds"},{"type":"constrict","details":"2d8+21"},{"type":"fast swallow"},{"type":"lingering poisonous cloud"},{"type":"mythic power","details":"10/day, surge +1d12"},{"type":"poison"},{"type":"swallow whole","details":"6d6 bludgeoning damage plus poison, AC 25, 52 hp"}],"spell_like_abilities_caster_level":26,"spell_like_abilities_concentration":36,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"detect scrying"}]},{"frequency":"at-will","spells":[{"spell":"discern location"},{"spell":"false vision","details":"see aura of security"},{"spell":"fog cloud"},{"spell":"greater dispel magic"},{"spell":"locate object"},{"spell":"major curse"},{"spell":"persuasive goad"}]},{"frequency":"1/day","spells":[{"spell":"breath of life"},{"spell":"dimensional lock"},{"spell":"limited wish"},{"spell":"mage's disjunction"},{"spell":"plane shift"},{"spell":"word of recall"}]},{"frequency":"3/day","spells":[{"spell":"geas/quest"},{"spell":"leashed shackles"},{"spell":"maze"},{"spell":"plant growth"},{"spell":"spell turning"},{"spell":"wall of stone"},{"spell":"wall of thorns"}]}],"strength":38,"dexterity":13,"constitution":30,"intelligence":15,"wisdom":24,"charisma":25,"baseatk":26,"cmb":44,"cmb_special":"+4 vs. grapple","cmd":51,"cmd_special":"+4 vs. grapple, can't be tripped","feats":[{"feat":"Blinding Critical"},{"feat":"Cleave","type":"mythic"},{"feat":"Critical Focus","type":"mythic"},{"feat":"Death from Above"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Iron Will","type":"mythic"},{"feat":"Multiattack"},{"feat":"Power Attack","type":"mythic"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"}],"skills":[{"skill":"Climb","value":38},{"skill":"Fly","value":11},{"skill":"Intimidate","value":36},{"skill":"Knowledge (geography)","value":26},{"skill":"Knowledge (local, religion)","value":18},{"skill":"Perception","value":44},{"skill":"Sense Motive","value":36},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":13},{"skill":"Survival","value":44},{"skill":"Swim","value":22},{"skill":"Use Magic Device","value":23}],"languages":["Abyssal","Celestial","Common","Draconic","Infernal","Sylvan"],"sq":[{"type":"amphibious"},{"type":"heroic challenge"},{"type":"mythic immortality"},{"type":"recuperation"},{"type":"secret lair"},{"type":"vengeful seeker"}],"environments":["any"],"organizations":["solitary"],"treasure":"triple, plus one artifact or major item","description_visual":"This immense dragon coils its long, serpentine body beneath spreading wings, its eyes glittering like burnished gold.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Agonizing Venom","kind":"Ex","details":"Any creature failing its saving throw against the dragon's breath weapon, poison, or poisonous blood is sickened with pain for 1 minute. A second, third, and fourth failed saving throw mean the creature is also staggered for 1 minute, nauseated for 1 minute, and helpless for 1 minute, respectively. This is a pain effect. If the dragon expends one use of mythic power when poisoning a creature, the dragon's breath weapon and poison overcome any poison immunity the target has."},{"type":"Aura of Security","kind":"Su","details":"A guardian dragon is alerted whenever a Tiny or larger creature enters its aura (as a mental alarm spell). If its dimensional lock spell-like ability is dispelled or destroyed, it may expend two uses of mythic power to cast it again. The dragon can use its false vision spell-like ability only within its aura, and the duration ends if the aura's area no longer includes the affected area."},{"type":"Heroic Challenge","kind":"Su","details":"Once per day, a guardian dragon can give a non-mythic creature the agile, arcane, divine, invincible, or savage mythic template. The dragon must expend a number of uses of mythic power equal to the amount the target creature's CR increases. The creature isn't under the dragon's control, but won't willingly attack the dragon unless magically forced to do so. Alternatively, the dragon can expend one use of mythic power to create difficult terrain in a 100-foot-radius burst; the type of difficult terrain is appropriate to the area (mud in plains, rubble in mountains, and so on). The effects of this ability persist as long as the dragon remains within 10 miles of the affected creature or area."},{"type":"Lingering Poisonous Cloud","kind":"Su","details":"The guardian dragon can expend one use of mythic power when it uses its breath weapon to have the cloud remain for 10 rounds, functioning as cloudkill. The dragon can expend one additional use of mythic power for this to function as mythic cloudkill."},{"type":"Poison","kind":"Ex","details":"Bite or swallow whole-injury; save Fort DC 33; frequency 1/round for 6 rounds; effect 1d4 Str and 1d4 Con; cure 2 consecutive saves."},{"type":"Secret Lair","kind":"Su","details":"A guardian dragon can spend 1 hour concentrating to create a labyrinthine extradimensional lair for itself and whatever it is guarding. This functions like greater create demiplane and creates a demiplane with the morphic, portal, shape, and structure properties. The demiplane is approximately a 500-foot-diameter sphere, and the dragon usually fills it with a maze of corridors (most of which are large enough for the Gargantuan dragon to move through) to confuse and delay invaders intent on stealing its treasure. The demiplane's portal is connected to a spot in the dragon's hidden lair, and over time the dragon usually brings guardian creatures from the Material Plane to add to the demiplane's defenses. The dragon can have only one demiplane active at a time, and the demiplane dissolves 10d10 minutes after the dragon leaves, so the dragon leaves only for a few minutes at a time or if its treasure has been stolen."},{"type":"Vengeful Seeker","kind":"Ex","details":"A guardian dragon gains the swift tracker and quarry abilities of a ranger when tracking or hunting any creature that has confirmed a critical hit against it, penetrated its spell resistance, or taken any amount of its treasure. Any divination spell-like ability a guardian dragon uses to locate such a creature or its treasure counts as the mythic version of the spell, if appropriate."}],"description":"A guardian dragon is an immense, serpentine dragon created by a deity to hide and guard a fabulous, legendary treasure. Spiriting its charge away to the farthest ends of the earth and beyond, the dragon maintains its eternal vigil surrounded by a garden, a labyrinth, a palace, or something uncanny, either building such a place itself or occupying a structure crafted for it by the deity. Over time, the guardian dragon enhances the defenses around its lair. As most guardian dragons have been protecting the same item for decades or centuries, a typical guardian dragon's lair is full of natural hazards and stocked with a variety of lesser mythic and non-mythic opponents that add to the lair's defenses. A mortal hero might brave the dangers of such a lair, seeking the dragon's prize, but the guardian's thirst for vengeance when recovering its charge is unending. The dragon considers any theft of its possessions an affront to its honor, and takes such an offense personally. With magic that allows it to find any creature at any distance, the dragon is relentless in pursuit of its lost items. Many enterprising thieves have escaped with a treasure, only to be located days or weeks later, killed, and dragged back to the dragon's lair with the stolen items. Because of its many victories over thieves and dragonslayers, a guardian dragon is usually in possession of a large collection of magic items, and it doesn't hesitate to make use of rings, scrolls, wands, and other items to protect itself or fortify its lair-or for instructing its lesser guardians on how to use these items. A guardian dragon might be willing to trade items it can't use for something more suitable, as long as the other party makes no attempt to take anything without permission (especially its charge, but it considers any theft reprehensible). A guardian dragon is 50 ft. long when fully uncoiled and weighs 7 tons.","ecology":"","habitat_society":""},{"name":"Hekatonkheires","cr":24,"xp":1228800,"alignment":"CE","size":"Colossal","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":6,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"120 ft."},{"type":"true seeing"}],"ac":42,"ac_touch":4,"ac_flat_footed":40,"ac_mods":"+8 armor, +2 Dex, +30 natural, -8 size","hp":516,"hd":"24d10+384","hdvalue":24,"hp_mods":["regeneration 10 (epic)"],"fort":30,"ref":12,"will":18,"defensive_abilities":["spell turning"],"dr":"20/epic and lawful","immunities":["aging","death effects","disease","mind-affecting effects"],"sr":35,"speed":[{"type":"land","speed":60}],"speed_mod":"air walk","melee":"+3 weapon +38 (6d6+22 plus hundred-handed whirlwind) or slam +37 (4d8+21 plus stun)","ranged":"rock +22 (8d8+31/18-20)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"rock throwing","details":"200 ft."},{"type":"stunning slam"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":36,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"spell turning"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"bestow curse"},{"spell":"break enchantment"},{"spell":"chain lightning"},{"spell":"find the path"},{"spell":"greater dispel magic"},{"spell":"sending"}]},{"frequency":"1/day","spells":[{"spell":"dominate monster"},{"spell":"greater spell immunity"},{"spell":"imprisonment"},{"spell":"storm of vengeance"}]},{"frequency":"3/day","spells":[{"spell":"greater scrying"},{"spell":"heal"},{"spell":"mass suggestion"}]}],"strength":48,"dexterity":15,"constitution":43,"intelligence":22,"wisdom":19,"charisma":24,"baseatk":24,"cmb":51,"cmb_special":"+2 vs. bull rush","cmd":63,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Combat Expertise"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":29,"special":"+41 when jumping"},{"skill":"Bluff","value":34},{"skill":"Climb","value":46},{"skill":"Craft (any)","value":33},{"skill":"Diplomacy","value":31},{"skill":"Escape Artist","value":29},{"skill":"Intimidate","value":34},{"skill":"Knowledge (history)","value":30},{"skill":"Knowledge (planes)","value":33},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":35},{"skill":"Survival","value":28}],"languages":["Abyssal","Celestial","Common","telepathy 300 ft."],"sq":[{"type":"hands of war"},{"type":"planar leap"}],"environments":["any"],"organizations":["solitary"],"treasure":"triple (50-100 various weapons)","description_visual":"This behemoth looks like a towering humanoid with fifty heads and twice as many hands, each wielding a different weapon.","group":"Titan","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Hands of War","kind":"Su","details":"Any weapon a hekatonkheires wields gains a +3 enhancement bonus while the titan holds it. A hekatonkheires's attacks are treated as epic and evil for the purposes of overcoming damage reduction. In addition, a hekatonkheires's multitude of arms allows it to effectively block attacks, granting it a +8 armor bonus to its AC."},{"type":"Hundred-Handed Whirlwind","kind":"Ex","details":"A hekatonkheires carries several dozen weapons of various types in its hundred hands, but when it attacks in melee, you don't have to resolve each of these as a separate attack. Instead, when the titan attacks with its weapons, it rolls its attacks normally (either one attack for a standard action, or four as a full-round action) and hits every creature in its reach each time an attack roll exceeds that creature's AC. If any such attack roll results in a possible critical hit, the critical is applied to one creature of the hekatonkheires's choosing. The hekatonkheires can choose to deal bludgeoning, piercing, or slashing damage as a free action on each separate hit."},{"type":"Planar Leap","kind":"Su","details":"A hekatonkheires traverses the planes by physically smashing through planar boundaries and crashing devastatingly into the target plane itself. Once per year as a full-round action, a hekatonkheires can, as part of a jump, plane shift to any other plane (as per the spell of the same name). It can only bring itself and its gear when it travels in this manner. When the hekatonkheires reaches its destination plane, it falls from the sky and crashes to the ground, creating a devastating explosion of thunder and fire. Any creature within 300 ft. of the point where the hekatonkheires lands (including the titan itself) takes 20d6 points of bludgeoning damage and 20d6 points of sonic damage (Reflex DC 38 half). The save DC is Constitution-based."},{"type":"Stunning Slam","kind":"Ex","details":"As a standard action, a hekatonkheires may forgo any weapon attacks to make a single slam attack against any creature in reach. If it hits, the target takes damage and must succeed at a DC 41 Fortitude save to avoid being stunned for 1d6 rounds. The save DC is Strength-based."}],"description":"Horrifying abominations shunned by the gods immediately upon their creation, the hekatonkheires are perhaps the most powerful and devastating race of titans in existence. When the titans-envious of the gods' divine strength—rebelled against the deities, the hekatonkheires were among the first to pick up arms, weary of the scorn their own creators felt for them. The betrayal of the Elysian titans led to the hekatonkheires' swift capture by the gods, who found the hekatonkheires' power to be so immense that they were not banished to the Abyss with their Thanatotic brethren. Instead, the gods cast the hekatonkheires into the furthest reaches of the multiverse they could find. There, the hekatonkheires drifted in expanses of nothingness for unknown eons, and the madness wrought upon them by isolation destroyed their memories. Yet from their madness these shattered monstrosities spawned progeny to\n\nreplace them in their pursuit to destroy, and some of these monstrous offspring discovered ways to break through planar boundaries and wander the multiverse freely.\n\nThe gods initially created only three hekatonkheires, seeking to make the ultimate warriors in order to guard the gates to the Abyss. These three ancient titans still drift in the unknown expanses between planes-the hekatonkheires that now walk the worlds are their lesser spawn. But these so-called \"lesser\" titans remain almost unimaginably powerful themselves. They have no knowledge of why their forgotten ancestors were originally banished, and so they wander in search of answers, all the while destroying entire worlds. They are warped engines of mayhem, their existence based wholly on the devastation of life and anything that might remind them of their age-old war against the gods, having inherited only the haunting ghosts of such memories from their ancestors.\n\nThose hekatonkheires who have emerged back into the multiverse have done so in different realms, and to date, no record of any two of these spawn meeting one another exists. It is fortunate that only one hekatonkheires is encountered on a world at any given time, as even scholars cannot fathom the power that would arise out of two or more of the titans' collective strength. They traverse the planes alone, caring not for allies of any sort until they can remember what their purpose was when they were born eons ago.\n\nThough hekatonkheires are as intelligent as the rest of their titan relatives, they wander with such destructive and seemingly mindless intentions that they spare no time in communicating with other creatures, especially those that would beg for mercy. The hekatonkheires were created to destroy, and so that is all they desire to do; the crushing blows of their fists and the goring slashes of their weapons speak for themselves. They serve no master, and halt their otherwise endless rampage only if called by their true names, which few-if any-mortals know. Those that do know these names speak them only in whispers, for their mere utterance seems to carry with it immeasurable power.\n\nA hekatonkheires can only be called via mighty spells such as gate if a conjurer knows the plane the titan is currently on, and only if the conjurer knows the true name of the hekatonkheires it is seeking to call. Only the mad or depraved would dare such a feat, however, as the might of one of these unique goliaths is so massive that the being cannot be controlled, and even if it is banished back to the realm from whence it came,\n\nit is never long before the hekatonkheires sets its sights on the world it visited so brief ly, if only to sate its lust for destroying it.\n\nEach hekatonkheires has 50 heads and 100 arms so that one is never caught off guard. The stones that it hurls with its 100 hands are as big as boulders, and those who have seen a hekatonkheires hurl such rocks and lived to tell the tale have said that it is as though an entire mountain is falling from the sky. In addition to their unworldly strength, hekatonkheires are known for their awesome control over the powers of lightning and thunder, and an individual hekatonkheires's arrival is often prefaced by an abrupt and tumultuous storm in the area. Like all titans, hekatonkheires are immortal, and don't die unless they are slain.\n\nA hekatonkheires is 50 ft. tall and weighs 25 tons.","ecology":"","habitat_society":""},{"name":"Nightripper","cr":24,"xp":1228800,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["unholy aura (DC 25)"],"ac":42,"ac_touch":25,"ac_flat_footed":31,"ac_mods":"+4 deflection, +11 Dex, +17 natural","hp":526,"hd":"27d10+378","hdvalue":27,"hp_mods":["regeneration 15 (good weapons or spells)"],"fort":27,"ref":30,"will":25,"dr":"15/cold iron and good","immunities":["charm and compulsion effects","death effects","electricity","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30},{"type":"fire","value":30}],"sr":35,"speed":[{"type":"land","speed":60}],"melee":"+5 vorpal bastard sword +43 (1d10+18/17-20), claw +31 (2d6+4/19-20 plus 2d6 bleed), 2 talons +31 (1d6+4/19-20 plus 2d6 bleed)","space":"5 ft.","reach":"5 ft. (15 ft. with talons)","special_attacks":[{"type":"curse of living death"},{"type":"slowing gaze"},{"type":"sneak attack","details":"+3d6"},{"type":"swift cuts"},{"type":"sword mastery"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":34,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"airwalk"},{"spell":"detect good"},{"spell":"detect law"},{"spell":"freedom of movement"},{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"phantasmal killer"},{"spell":"spiked pit"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"reverse gravity"},{"spell":"summon","details":"level 9, any demon or combination of demons whose total combined CR is 20 or lower 100%"},{"spell":"time stop"},{"spell":"weird"}]},{"frequency":"3/day","spells":[{"spell":"acid pit"},{"spell":"harm"},{"spell":"hungry pit"},{"spell":"quickened blade barrier"}]}],"strength":29,"dexterity":32,"constitution":39,"intelligence":18,"wisdom":23,"charisma":24,"baseatk":27,"cmb":36,"cmd":61,"feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dazzling Display"},{"feat":"Deadly Stroke"},{"feat":"Exotic Weapon Proficiency (bastard sword)","type":"bonus"},{"feat":"Greater Feint"},{"feat":"Greater Weapon Focus (bastard sword)","type":"bonus"},{"feat":"Greater Weapon Specialization (bastard sword)","type":"bonus"},{"feat":"Improved Critical (bastard sword)"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (talon)"},{"feat":"Improved Disarm"},{"feat":"Improved Feint"},{"feat":"Power Attack"},{"feat":"Quick Draw"},{"feat":"Quicken Spell-Like Ability (blade barrier)"},{"feat":"Shatter Defenses"},{"feat":"Weapon Focus (bastard sword)","type":"bonus"},{"feat":"Weapon Specialization (bastard sword)","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":41},{"skill":"Intimidate","value":37},{"skill":"Knowledge (history)","value":31},{"skill":"Knowledge (local)","value":31},{"skill":"Knowledge (religion)","value":31},{"skill":"Knowledge (nobility)","value":34},{"skill":"Perception","value":36},{"skill":"Sense Motive","value":36},{"skill":"Stealth","value":41},{"skill":"Use Magic Device","value":37}],"languages":["Abyssal","Celestial","Common","Draconic","telepathy 300 ft."],"sq":[{"type":"nascent demon lord traits"}],"environments":["any (Kurnugia)"],"organizations":["solitary"],"treasure":"triple (+5 keen vorpal bastard sword)","description_visual":"Twin talons attached to grotesque back-appendages drip blood from this hideously emaciated, jackal-legged albino demon.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Curse of Living Death","kind":"Su","details":"Once per round, as a free action as he kills a living creature, Nightripper can choose to afflict that target with the curse of living death. The target can resist this curse with a successful DC 30 Will save right before it dies, allowing the victim to die normally. If the victim fails its save, it enters a sort of half-living state; it becomes completely helpless, unable to take any actions whatsoever, but remains conscious and aware of the world, and of the pain in its body. It cannot be resurrected or otherwise restored to life until the curse is lifted. While the curse remains in effect, the victim takes 1d4 points of Intelligence, Wisdom, and Charisma drain every day as any lingering shreds of sanity are blasted away. When each ability score is drained to zero, the DC of the curse increases by +4. A character suffering the curse of living death can remain in this state forever, but as long as any one of her mental ability scores is at zero, she is capable only of enduring pain and cannot observe the world around her. Even if the character's body is destroyed, the cursed victim's consciousness remains as a disembodied and invisible presence at the site of this destruction, and cannot be resurrected or released to the afterlife. The save DC is Charisma-based. Nascent Demon Lord Traits A nascent demon lord is a powerful demon that has not yet made the full transition from unique demon to full demon lord of an Abyssal realm. They have several traits, as summarized here. • Immunity to charm and compulsion effects, death effects, electricity, and poison. • Resistance to acid 30, cold 30, and fire 30. •."},{"type":"Summon","kind":"Sp","details":"Once per day, Nightripper can summon any demon or combination of demons whose total combined CR is 20 or lower. This ability always works, and is equivalent to a 9th-level spell. • Telepathy 300 ft. • Nightripper's natural weapons, as well as any weapon he wields, are treated as chaotic, epic, and evil for the purpose of overcoming damage reduction. • Nightripper can grant spells to his worshipers. He grants access to the domains of Chaos, Darkness, Evil, and Strength. His favored weapon is the bastard sword."},{"type":"Slowing Gaze","kind":"Su","details":"Slowed (as the slow spell) for 1 round, 30 ft., Will DC 30 negates. The save DC is Charisma-based."},{"type":"Swift Cuts","kind":"Ex","details":"As long as he is attacking with a sword, Nightripper treats foes who are staggered, nauseated, or under the effects of a slow spell (or similar effects, such as his gaze) as if they were flat-footed."},{"type":"Sword Mastery","kind":"Ex","details":"Nightripper possesses several sword-related bonus feats normally restricted to fighters."}],"description":"Even today, centuries after his 13th and final execution, memories of Riktus Scroon continue to haunt the nightmares of those who live along the northern coastlines of the Inner Sea. During his reign of horror, the man who would come to be known as the Nightripper used his position in the now disbanded Graven Guard of Taldor to move along the shipping lanes with ease. His position among the mercenary company afforded him time in countless settlements from Golisfar to Corentyn, and in these unsuspecting towns he hunted. Scroon preferred young victims, that their vanishing would cause the most distress possible-his favorites were young adults freshly in love, although he seemed to have had no preference between man or woman. He abducted his victims with astonishing skill, tormenting them for hours with his blades before leaving them broken and bleeding to death at the bottom of a specially prepared pit far outside of town. The mass murderer was finally captured by Cesandra Dayne, an obsessed priest of Sarenrae who had lost her fiancee and her father to Scroon. Only by forsaking the teachings of her church was she able to trap the murderer in the slums of Almas, and although the resulting fight saw the death of a dozen innocent bystanders, in the end Cesandra had her man alive.\n\nAfter Scroon was turned over to the law in his hometown of Oppara, the authorities thought to prosecute him for the deaths of no fewer than 46 known victims. When Scroon gleefully bragged of having murdered nearly a thousand men, women, and children, the authorities were eager to write off his ravings, yet after Scroon provided exacting details to the sites of 953 victims, and one after the other his directions led to actual graves, the killer's sentencing was hastened-death by hanging. Yet Scroon survived. One after the other, attempts to execute the Nightripper failed-headsmen died of fright as they lifted the axe, guillotines malfunctioned, magic failed. Each botched execution left Scroon more disfigured, but his legend grew. The 13th and final execution put the man down once and for all-or so it was hoped.\n\nScroon's soul went to the Boneyard, where something amazing happened-he passed through to the Abyss with his mind and memories intact. So remarkable was his retention of his identity that it drew the attention of Lamashtu herself, who pulled the killer's soul from the shuddersome bosom of the Abyss and made him her personal assassin, raising him from a broken shell of a soul to a nascent demon lord with greater power than he'd ever hoped for in life. His form had changed, transforming into a shape more befitting one of his horrific nature, yet his mind remained sharp and clear. Nightripper harbors a strong desire for revenge, but for now he serves dutifully as Lamashtu's favored torturer and assassin and as the lord of the dungeons below her palace in the Abyssal realm of Kurnugia. But it is said that someday, when he has repaid his debt to the Mother of Demons for his ascension and rescue from the dregs of the Abyss, the Nightripper will return to his old haunts. Only this time, it will not be individuals he breaks and bleeds and buries in his pits-it will be entire cities.","ecology":"","habitat_society":""},{"name":"Yamasoth","cr":24,"xp":1228800,"alignment":"CE","size":"Gargantuan","type":"outsider","subtypes":["chaotic","evil","extraplanar","qlippoth"],"init":11,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"true seeing"}],"auras":["cloak of chaos (DC 24)"],"ac":43,"ac_touch":18,"ac_flat_footed":35,"ac_mods":"+4 deflection, +7 Dex, +1 dodge, +25 natural, -4 size","hp":526,"hd":"27d10+378","hdvalue":27,"hp_mods":["regeneration 15 (lawful)"],"fort":33,"ref":28,"will":18,"dr":"15/cold iron and lawful","immunities":["cold","death effects","mind-affecting effects","poison"],"resists":[{"type":"acid","value":30},{"type":"electricity","value":30},{"type":"fire","value":30}],"sr":35,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"maw +36 (2d10+13/19-20), 4 bites +36 (2d8+13/19-20), 6 tentacles +34 (2d6+6/19-20 plus grab)","space":"20 ft.","reach":"20 ft. (30 ft. with tentacles)","special_attacks":[{"type":"constrict","details":"2d6+13"},{"type":"gaze weapon"},{"type":"horrific appearance","details":"DC 29"},{"type":"polymorph plague"},{"type":"rend","details":"4 bites, 2d8+19"},{"type":"tentacle transformation"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":34,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"cloak of chaos"},{"spell":"detect good"},{"spell":"detect law"},{"spell":"fly"},{"spell":"freedom of movement"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"desecrate"},{"spell":"greater dispel magic"},{"spell":"greater teleport"},{"spell":"statue"},{"spell":"stone shape"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"earthquake"},{"spell":"summon","details":"level 9, any qlippoth or combination of qlippoth whose total combined CR is 20 or lower 100%"}]},{"frequency":"3/day","spells":[{"spell":"flesh to stone"},{"spell":"phase door"},{"spell":"polymorph any object"},{"spell":"quickened baleful polymorph"},{"spell":"wall of stone"}]}],"strength":36,"dexterity":25,"constitution":38,"intelligence":25,"wisdom":21,"charisma":22,"baseatk":27,"cmb":44,"cmb_special":"+4 vs. grapple","cmd":66,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (baleful polymorph)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":45},{"skill":"Intimidate","value":36},{"skill":"Knowledge (arcana)","value":37},{"skill":"Knowledge (planes)","value":37},{"skill":"Knowledge (dungeoneering)","value":34},{"skill":"Knowledge (history)","value":34},{"skill":"Knowledge (nature)","value":34},{"skill":"Knowledge (religion)","value":34},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":35},{"skill":"Spellcraft","value":37},{"skill":"Stealth","value":25},{"skill":"Use Magic Device","value":36}],"languages":["Abyssal","telepathy 300 ft."],"sq":[{"type":"qlippoth lord traits"}],"environments":["any (Sekatar-Seraktis)"],"organizations":["solitary","group (Yamasoth plus 2d6 gongorinans and 2d6 various polymorphed minions)"],"treasure":"triple","description_visual":"Writhing, hook-covered tentacles unfurl from this behemoth's body, at the center of which gapes a maw with a red eye in its throat.","source":"AP 64","special_abilities":[{"type":"Gaze Weapon","kind":"Su","details":"As a free action at the start of his turn, Yamasoth can gape his central maw wide to expose the horrific red eye lodged in what should be his throat. This gaze weapon has a range of 30 ft., and polymorphs creatures affected by it into giant vermin, animals, or magical beasts (Fortitude DC 37 resists). Yamasoth chooses what creatures to transform victims into as they fail their saving throws. This effect otherwise functions as polymorph any object (CL 20th), and is a polymorph effect. Yamasoth can keep his maw open for up to 3 consecutive rounds, after which his throat-eye closes and this gaze weapon cannot be used again for 1 minute. The save DC is Constitution-based."},{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to Yamasoth's horrific appearance are stunned. At the start of each round thereafter, a creature stunned in this way can make a choice—fight the overwhelming chaos and horror and attempt a new DC 29 Will save to end the stun effect and act normally on that round, or accept the chaos into its soul and automatically succeed at the save to recover from the stun effect. This latter option immediately shifts the creature's alignment one step closer to chaotic evil. This shift in alignment can be fixed via atonement, but counts as a voluntary alignment shift for the purposes of atonement's material component requirements. A creature that becomes chaotic evil as a result of this also becomes a willing minion and ally of Yamasoth."},{"type":"Maw","kind":"Ex","details":"Yamasoth's central maw is a primary attack that threatens a critical hit on a roll of 19-20. A creature hit by Yamasoth's maw while his gaze weapon is active takes a -4 penalty on its next saving throw against the gaze attack."},{"type":"Polymorph Plague","kind":"Su","details":"Any creature that has been affected by one of Yamasoth's polymorph effects becomes \"contagious.\" For 24 hours after the creature's initial transformation, any other creature that touches or is touched by the polymorphed creature must succeed at a Fortitude save (DC = 10 + 1/2 the polymorphed creature's HD + the polymorphed creature's Constitution modifier) to resist polymorphing into a creature identical to the current form of the polymorphed creature. Qlippoth Lord Traits A qlippoth lord is a powerful and unique qlippoth that rules a significant portion of an Abyssal realm. Qlippoth lords possess the following traits. • Immunity to cold, death effects, mind-affecting effects, and poison. • Resistance to acid 30, electricity 30, and fire 30. •."},{"type":"Horrific Appearance","kind":"Su","details":"This ability functions similarly to the typical qlippoth ability, save that qlippoth lords' horrific appearances often create physical effects and changes in their victims. Despite these physical effects, a qlippoth lord's horrific appearance remains a mind-affecting effect. •."},{"type":"Summon Qlippoth","kind":"Sp","details":"Once per day, a qlippoth lord can summon any qlippoth or combination of qlippoth whose total combined CR is 20 or lower. This ability always works, and is equivalent to a 9th-level spell. • Telepathy 300 ft. • A qlippoth lord's natural weapons, as well as any weapon it wields, are treated as chaotic, epic, and evil for the purpose of overcoming damage reduction. • Qlippoth lords can grant spells to their worshipers. Granting spells doesn't require any specific action on the qlippoth lord's behalf. All qlippoth lords grant access to the domains of Chaos and Evil; in addition, they grant access to two other domains and a favored weapon that vary according to each qlippoth lord's themes and interests."},{"type":"Tentacle Transformation","kind":"Su","details":"At the start of every odd-numbered round, three of Yamasoth's tentacle tips transform into one of three different types of appendages-a serpent's head, a clawed hand, or a metallic blade. The three tentacles all change into the same type of attack, and the change persists for 1 full round, after which the three tentacles revert to normal tentacles on every even-numbered round. While transformed, the limbs make the following types of attacks instead of tentacle attacks. • Blade: talon +36 (3d6+13/19-20) • Clawed Hand: claw +36 (2d6+13 plus bleed damage equal to the damage dealt by the claw) • Serpent Head: bite +36 (1d8+13 plus poison: bite—injury; save Fort DC 37; frequency 1/round for 12 rounds; effect 1d4 Dex drain and slowed for 1 round; cure 3 consecutive saves)"}],"description":"Yamasoth, known also as the Polymorph Plague, dwells in the endless cavern realm of Sekatar- Seraktis in the Abyss. Constantly at war with bickering balor lords and other powerful demons, Yamasoth has held his own as the lord of the Abyss's largest, most centralized region: the Kingdom of New Flesh. The \"new flesh\" in question consists of the qlippoth lord's subjects, men and women from countless worlds who may have been kings and queens at one time, but here are nothing more than base monsters, vermin, and beasts to serve at Yamasoth's whim. Some he feeds upon. Others he keeps for his harem. But the bulk of the denizens of the Kingdom of New Flesh are soldiers. In this army, other qlippoth serve as commanders and generals, particularly Yamasoth's favored minions, the gongorinans.\n\nUnlike most qlippoth, Yamasoth doesn't necessarily prefer to kill but rather to transform. A human who sins and dies produces a soul that fuels the demonic horde, but a dumb beast or feral monster who dies is merely carrion. By transforming free-willed mortals into monsters, Yamasoth's Army of the New Flesh only becomes more capable of ending worlds. Yamasoth's centuries-long alliance with Runelord Alaznist may have eventually resulted in such an assault on Golarion, but the devastation of Earthfall ended those plans before Yamasoth's burgeoning realm could finalize its gestation-proof that even in the greatest of disasters, some good is wrought.\n\nYamasoth's interest in transformations goes far beyond mere polymorphing. The qlippoth lord is also fascinated by the act of fleshwarping and reworking life into new forms of mutants. Rumors state that the nature of the experiments that take place deep in the Kingdom of New Flesh closely mimic those the daemons performed in the Abyss so long ago that resulted in the first demons. In fact, some dissident demonologists claim Yamasoth himself is a nascent demon lord, and is in fact that first, primal demon born of daemonic tampering with Abyssal quintessence and sinful souls.","ecology":"","habitat_society":""},{"name":"Balor Lord","cr":25,"xp":1638400,"race":"balor lord","classes":[{"class":"barbarian","level":5}],"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"true seeing"}],"auras":["flaming body","unholy aura (DC 27)"],"ac":33,"ac_touch":17,"ac_flat_footed":27,"ac_mods":"+4 deflection, +6 Dex, +16 natural, -1 size, -2 rage","hp":518,"hd":"20d10+5d12+375","hdvalue":25,"fort":31,"ref":17,"will":25,"defensive_abilities":["improved uncanny dodge","trap sense +1"],"dr":"15/cold iron and good","immunities":["electricity","fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":31,"speed":[{"type":"land","speed":50},{"type":"fly","speed":90,"maneuverability":"good"}],"melee":"(rage) +1 vorpal unholy longsword +40 (2d6+17), +1 vorpal flaming whip+39 (1d4+9 plus 1d6 fire and entangle) or 2 slams +40(1d10+16)","space":"10 ft.","reach":"10 ft. (20 ft. with whip)","special_attacks":[{"type":"rage","details":"27 rounds/day"},{"type":"rage powers","details":"knockback"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":37,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"},{"spell":"unholy aura"}]},{"frequency":"at-will","spells":[{"spell":"dominate monster"},{"spell":"greater dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"power word stun"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"fire storm"},{"spell":"implosion"},{"spell":"summon","details":"level 9, any 1 CR 19 or lower demon 100%"}]},{"frequency":"3/day","spells":[{"spell":"quickened telekinesis"}]}],"strength":43,"dexterity":23,"constitution":44,"intelligence":24,"wisdom":26,"charisma":29,"baseatk":25,"cmb":41,"cmd":66,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Greater Two-Weapon Fighting"},{"feat":"Improved Initiative"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (telekinesis)"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":31},{"skill":"Bluff","value":37},{"skill":"Diplomacy","value":37},{"skill":"Fly","value":36},{"skill":"Intimidate","value":37},{"skill":"Knowledge (history)","value":29},{"skill":"Knowledge (nobility)","value":29},{"skill":"Knowledge (planes)","value":35},{"skill":"Knowledge (religion)","value":28},{"skill":"Perception","value":44},{"skill":"Sense Motive","value":36},{"skill":"Stealth","value":30},{"skill":"Use Magic Device","value":37}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"sq":[{"type":"death throes"},{"type":"fast movement"},{"type":"lifedrinker"},{"type":"vorpal strike"},{"type":"whip mastery"}],"environments":["any (Abyss)"],"organizations":["solitary","warband (1 balor and 2-5 glabrezus)"],"treasure":"standard (+1 vorpal unholy longsword, +1 vorpal flaming whip)","description_visual":"This towering, burning demon wears black, spiky armor and carries two weapons-a jagged sword and a whip of flames.","group":"Demon","source":"PFRPG Bestiary","special_abilities":[{"type":"Rage","kind":"Ex","details":"This balor lord can rage for 27 rounds per day, and gains +4 to Strength and Constitution, and -2 to."},{"type":"AC Knockback","kind":"Ex","details":"Once per round, the balor lord can make a bull rush attempt against one target in place of a melee attack. If successful, the target takes damage equal to the lords's Strength modifier and is moved back as normal. The balor lord doesn't need to move with the target if successful. This doesn't provoke an attack of opportunity."},{"type":"Scent","kind":"Ex","details":"The balor lord gains the scent ability while raging and can use this ability to locate unseen foes."},{"type":"Death Throes","kind":"Su","details":"When killed, a balor lord explodes in a blinding flash of fire that deals 100 points of damage (half fire, half unholy damage) to anything within 100 ft. A Reflex save DC 35 halve the damage, this DC increases to 37 if the balor lord was killed in rage as the save DC is Constitution-based."},{"type":"Entangle","kind":"Ex","details":"If a balor lord strikes a Medium or smaller foe with its whip, the balor can immediately attempt a grapple check without provoking an attack of opportunity. If the balor wins the check, it draws the foe into an adjacent square. The foe gains the grappled condition, but the balor doesn't."},{"type":"Flaming Body","kind":"Su","details":"A balor lord's body is covered in dancing flames. Anyone striking a balor with a natural weapon or unarmed strike takes 1d6 points of fire damage. A creature that grapples a balor or is grappled by one takes 6d6 points of fire damage each round the grapple persists."},{"type":"Lifedrinker","kind":"Su","details":"Whenever the balor lord slays a living foe, it receives the benefits of a heal spell (CL 20th). This ability can activate up to once per round."},{"type":"Vorpal Strike","kind":"Su","details":"Any slashing weapon a balor lord wields (including its standard longsword and whip) gains the vorpal weapon quality. Weapons retain this quality for one hour after the balor releases the weapon, but after this the weapon reverts to its standard magical qualities, if any."},{"type":"Whip Mastery","kind":"Ex","details":"A balor lord treats a whip as a light weapon for the purposes of two-weapon fighting, and can inflict lethal damage on a foe regardless of the foe's armor."}],"description":"Even more terrible than the typical balor are those who don't call a demon lord their master, but instead are masters themselves. A balor lord typically rules over a region no larger than half the size of the realm in which it resides (as only full demon lords can command the rule of an entire Abyssal realm), and even though most balor lords rule much smaller regions (generally areas comparable in size to a single continent), their power is vast indeed. A balor lord is typically a CR 21 to CR 25 monster (a range shared with the various unique nascent demon lords, with the range of CR 26 and above being the domain of the demon lords themselves), and as such serves quite well as the final villain in a long-running campaign. The majority of balor lords have several levels of barbarian, fighter, or ranger (although ranger balor lords never form bonds with animals), but some instead have levels of bard, rogue, sorcerer, or wizard. Cleric balor lords are unknown, as they see themselves as objects of worship, not the other way around, although rumors persist of powerful balor clerics that directly serve demon lords or even evil gods. In addition to any benefits a balor lord might gain from its class levels, all balor lords possess one additional unique ability over and above those granted by its race and class. Listed here are three sample balor lord abilities, but these samples are by no means the entirety of the strange powers a balor lord might wield.\n\nLifedrinker (Su)Whenever the balor lord slays a living foe, it receives the benefits of a heal spell (CL 20th). This ability can activate up to once per round.\n\nMaster of Magic (Su) The balor lord has additional spell-like abilities (20 spell levels' worth of 1st-4th level spells usable at will and 20 spell levels' worth of 5th-8th level spells usable 3 times a day).\n\nSoul Swallow (Su)As a standard action, the balor lord can inhale the soul of a living creature within 30 ft. The target must make a Fortitude save (DC 10 + 1/2 balor lord's racial HD + the balor lord's Charisma modifier) or die. The body of a humanoid creature killed in this manner immediately transforms into a demon under the balor lord's command (a babau, succubus, or shadow demon, according to the balor lord's whim).","ecology":"","habitat_society":""},{"name":"Drakainia","cr":25,"xp":1638400,"alignment":"NE","size":"Huge","type":"aberration","subtypes":["mythic"],"init":9,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"lifesense"},{"type":"true seeing"}],"auras":["gestation (30 ft.)"],"ac":48,"ac_touch":13,"ac_flat_footed":43,"ac_mods":"+5 Dex, +35 natural, -2 size","hp":642,"hd":"25d8+530","hdvalue":25,"hp_mods":["regeneration 10 (negative energy)"],"fort":28,"ref":15,"will":6,"dr":"10/epic","immunities":["bleed","disease","poison","polymorph effects"],"sr":36,"speed":[{"type":"land","speed":50},{"type":"climb","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +31 (4d8+14/16-20/x4), gore +28 (4d6+7), 4 tentacles +29 (2d6+7)","space":"15 ft.","reach":"15 ft. (20 ft. with claws)","special_attacks":[{"type":"impregnate surrogate"},{"type":"mythic power","details":"10/day, surge +1d12"},{"type":"razor claws"},{"type":"well of life"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":42,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"dimension door"}]},{"frequency":"1/day","spells":[{"spell":"antimagic field"},{"spell":"destruction"},{"spell":"mythic regenerate"}]},{"frequency":"3/day","spells":[{"spell":"antilife shell"},{"spell":"break enchantment"},{"spell":"contagion"},{"spell":"dimension door"},{"spell":"quickened cure serious wounds"}]}],"strength":38,"dexterity":20,"constitution":46,"intelligence":29,"wisdom":21,"charisma":41,"baseatk":18,"cmb":5,"cmd":17,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes","type":"mythic"},{"feat":"Great Fortitude","type":"mythic"},{"feat":"Improved Initiative"},{"feat":"Iron Will","type":"mythic"},{"feat":"Lightning Reflexes","type":"mythic"},{"feat":"Multiattack"},{"feat":"Quick Channel"},{"feat":"Quicken Spell-Like Ability (cure serious wounds)"},{"feat":"Selective Channeling"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon FocusM (claw)"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Bluff","value":40},{"skill":"Climb","value":45},{"skill":"Diplomacy","value":40},{"skill":"Handle Animal","value":20},{"skill":"Heal","value":30},{"skill":"Intimidate","value":43},{"skill":"Knowledge (arcana)","value":34},{"skill":"Knowledge (dungeoneering)","value":34},{"skill":"Knowledge (nature)","value":34},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":30},{"skill":"Spellcraft","value":37},{"skill":"Swim","value":50},{"skill":"Use Magic Device","value":40}],"languages":["Abyssal","Aklo","Aquan","Auran","Celestial","Common","Draconic","Ignan","Infernal","Terran"],"sq":[{"type":"birth spawn"},{"type":"invert birth"},{"type":"polymorphism"},{"type":"transfer suffering"}],"environments":["any"],"organizations":["solitary"],"treasure":"double","description_visual":"This woman's upper body is shapely and beautiful, but her lower body is bloated, with pulsating tumors and writing tentacles.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Birth Spawn","kind":"Ex","details":"As a full-round action, a drakainia can give birth to a spawn, which is a Large or smaller creature of her choice with a single random mutation (. Each day she can produce any number of creatures whose combined total base CR doesn't exceed 3 + her Constitution modifier (usually 21)."},{"type":"Gestation Aura","kind":"Su","details":"A drakainia's aura pulses with developing life. All poisons or diseases active within her 30-foot aura have an onset of 1 round and a frequency of 1/minute. Impregnated creatures within her aura gestate in 2d4 rounds. Any creature born within her aura gains a mutation as if it were the drakainia's spawn, though if the creature's parent was not impregnated by the drakainia, the creature born is an infant of the kind its biological parents would produce, and doesn't count toward the CR limit the drakainia can spawn per day."},{"type":"Impregnate Surrogate","kind":"Su","details":"A drakainia can disgorge a monstrous embryo into the mouth of a living, corporeal creature that is pinned or helpless. She makes a grapple combat maneuver check, and if she succeeds she impregnates that creature regardless of its gender. A mythic character must succeed at a DC 38 Fortitude saving throw to avoid being impregnated; a non-mythic character is impregnated automatically. An impregnated creature's pregnancy lasts for 2d4 rounds. During this pregnancy, the victim is nauseated until the monster bursts forth from the victim's abdomen, which deals 10d6 points of damage to the pregnant creature and applies the broken condition to any armor it is wearing. Remove disease (DC 28) eliminates the unnatural embryo. Alternatively, as a full-round action another creature can attempt to cut out the growing monster with a DC 38 Heal check. On a successful check, the offspring is removed, and the formerly pregnant creature takes 1d4 points of bleed damage. On failed check, the pregnant creature takes 2d6 points of bleed damage and is stunned for 1 round, but the offspring isn't removed. The creature spawned by means of this impregnation is any creature of the drakainia's choice that is at least one size category smaller than the creature she impregnated. These spawn count against the drakainia's daily CR allowance for birth spawn."},{"type":"Invert Birth","kind":"Su","details":"When a drakainia uses her dimension door spell-like ability, instead of the normal range, she can choose to teleport to any space occupied by one of her spawn that is within 1 mile of her. She doesn't need line of sight or knowledge of the spawn's location. If she chooses a spawn that is farther than a mile away, she doesn't lose the use of the spell-like ability, but does lose the action. On arrival, she explodes out from her offspring, destroying it entirely."},{"type":"Polymorphism","kind":"Ex","details":"The spawn gestating inside the drakainia constantly alter her internal construction, making her immune to bleed, disease, poison, and polymorph effects. When she is subject to a critical hit or a sneak attack, this polymorphism grants her a 75% chance of negating such attacks."},{"type":"Razor Claws","kind":"Ex","details":"A drakainia's claws are razor sharp with a critical threat range of 17-20 and a critical multiplier of x4."},{"type":"Transfer Suffering","kind":"Su","details":"As a swift action, a drakainia can transfer a single harmful spell effect or condition from herself to one of her offspring that is currently within her gestation aura."},{"type":"Well of Life","kind":"Su","details":"A drakainia can unleash the primal life energy within in her body to channel positive energy as if she were a 20th-level cleric (DC 35). She can use this ability 18 times per day and can choose to expend 1 use of mythic power at each use to maximize the damage healed."}],"description":"Primal life energy, raw and uncontrolled, seethes through this mother of monsters. Her churning, distended belly mocks creation, birthing horrors and dismal failures. The weak are torn apart in the writhing mass of her nursery, while the strong transcend their hideous origins to become creatures of greatness in their own right. She is always encountered with at least a handful of her favored children, as well as other progeny she can sacrifice to protect herself. With their help, she impregnates those who come across her with twisted, monstrous life.\n\nDRAKAINIA SPAWN\n\nWhen a drakainia spawns, either through her own body or through a surrogate, what issues forth is a mutated abomination. Any impregnated creature that's within the drakainia's gestation aura has a child of the parents' race, but with one of the following mutations.\n\nd% Mutation 01-10 Fatal Mutation The creature is birthed stillborn and horribly disfigured. 11-20 Covered in Eyes (Ex) Eyes cover the front and back of the creature's head. It gains all-around vision. 21-30 Chameleon Scales (Ex) This creature is covered in scales that shift their hue to blend in with their surroundings. The creature gains a +8 racial bonus on Stealth checks and gains hide in plain sight. 31-40 Poison Glands (Ex) The creature has a pair of poison sacs near its mouth. It gains immunity to poison, and three times per day it can spit a dose of poison up to 20 ft. as a ranged touch attack. Poison: Contact-injury; save Fort DC 10 + 1/2 the creature's HD + its Constitution modifier; frequency 1/round for 6 rounds; effect 1d3 Con damage; cure 1 save. 41-50 Sticky (Ex) The creature's limbs are covered in tiny, hooked hairs that give its skin a downy appearance. It gains the grab ability on its primary natural attacks (if it has any) or its unarmed strike, and a +8 racial bonus on Climb checks. 51-60 Serpent-Headed Tail (Ex) The creature has a tail that ends in a snake head. This provides a +4 circumstance bonus on Perception checks and a primary bite attack (1d3 + the creature's Strength modifier for a Medium creature). In addition, the creature gains Improved Trip as a bonus feat. 61-70 Vestigial Companion (Ex) The creature has the head of an animal (usually a goat, chicken, or dog) growing out of its back or torso, providing the scent ability. If the base creature already has scent, this mutation allows it to determine the direction of a particular scent as a free action. 71-80 Multiple Heads (Ex) The creature has 2d4 heads, granting it a +4 racial bonus on saving throws against illusions and enchantments and a +8 racial bonus on Perception checks. The creature speaks an additional number of languages equal to its total number of heads. Each head speaks with a different voice. 81-90 Tentacles (Ex) The creature's legs are replaced with multiple tentacles. It can't be tripped and gains a +8 racial bonus to CMD and a +8 racial bonus on combat maneuver checks to grapple. 91-99 Impenetrable Skin (Ex) The drakainia spawn's skin is tough and scaly. It gains DR/- equal to half its HD (maximum 10). 100 Favored Spawn (Su) Favored spawn are those a drakainia has marked as successful or quasi-successful mutations. These powerful spawn gain a +4 luck bonus on all saving throws, a +4 increase to natural armor, a +4 inherent bonus to two ability scores, and 1 mythic rank.","ecology":"","habitat_society":""},{"name":"Lorthact","cr":25,"xp":1638400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"auras":["unholy aura"],"ac":45,"ac_touch":29,"ac_flat_footed":33,"ac_mods":"+6 armor, +5 deflection, +11 Dex, +1 dodge, +2 luck, +10 natural","hp":560,"hd":"32d10+384","hdvalue":32,"hp_mods":["regeneration 5 (good weapons or spells)"],"fort":26,"ref":31,"will":30,"defensive_abilities":["evasion"],"dr":"20/good and silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":30},{"type":"cold","value":30}],"sr":36,"speed":[{"type":"land","speed":30}],"melee":"2 claws +44 (1d6+6 plus 1 Int drain) or  +2 quarterstaff +40 (1d6+11 plus 1 Intelligence drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"Intelligence drain"},{"type":"scholastic masquerade"},{"type":"spell reservoir"}],"spell_like_abilities_caster_level":25,"spell_like_abilities_concentration":37,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"mind blank"},{"spell":"tongues"},{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"blasphemy"},{"spell":"dominate person"},{"spell":"freedom of movement"},{"spell":"greater arcane sight"},{"spell":"greater dispel magic"},{"spell":"greater invisibility"},{"spell":"greater scrying"},{"spell":"greater shadow conjuration"},{"spell":"greater shadow evocation"},{"spell":"greater teleport"},{"spell":"mass suggestion"},{"spell":"programmed image"},{"spell":"unholy aura"}]},{"frequency":"1/day","spells":[{"spell":"dominate monster"},{"spell":"limited wish"},{"spell":"mage's disjunction"},{"spell":"prismatic sphere"},{"spell":"time stop"}]},{"frequency":"3/day","spells":[{"spell":"banishment"},{"spell":"empowered horrid wilting"},{"spell":"polymorph any object"},{"spell":"quickened greater dispel magic"},{"spell":"spell turning"}]}],"strength":22,"dexterity":33,"constitution":35,"intelligence":30,"wisdom":26,"charisma":37,"baseatk":32,"cmb":38,"cmd":65,"feats":[{"feat":"Deflect Arrows"},{"feat":"Destructive Dispel"},{"feat":"Dispel Synergy"},{"feat":"Dodge"},{"feat":"Empower Spell-Like Ability (horrid wilting)"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Greater Spell Penetration"},{"feat":"Improved Great Fortitude"},{"feat":"Improved Unarmed Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (greater dispel magic)"},{"feat":"Spell Penetration"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":36},{"skill":"Bluff","value":48},{"skill":"Craft (alchemy)","value":30},{"skill":"Diplomacy","value":48},{"skill":"Disguise","value":48},{"skill":"Fly","value":23},{"skill":"Intimidate","value":45},{"skill":"Knowledge (arcana)","value":45},{"skill":"Knowledge (planes)","value":45},{"skill":"Knowledge (dungeoneering)","value":20},{"skill":"Knowledge (engineering)","value":20},{"skill":"Knowledge (geography)","value":20},{"skill":"Knowledge (nobility)","value":20},{"skill":"Knowledge (religion)","value":20},{"skill":"Knowledge (history)","value":30},{"skill":"Knowledge (local)","value":30},{"skill":"Perception","value":43},{"skill":"Perform (act)","value":23},{"skill":"Sense Motive","value":30},{"skill":"Sleight of Hand","value":30},{"skill":"Spellcraft","value":45},{"skill":"Stealth","value":46},{"skill":"Use Magic Device","value":45}],"languages":["Abyssal","Aklo","Azlanti","Celestial","Common","Draconic","Dwarven","Elven","Giant","Ignan","Infernal","Undercommon","telepathy 300 ft."],"sq":[{"type":"infernal duke traits"},{"type":"temporal anomaly"}],"environments":["any (Korvosa)"],"organizations":["solitary"],"treasure":"triple","description_visual":"This devilish humanoid has five horns growing out of his forehead that resemble a crown. He stands on stout cloven hooves.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Infernal Duke Traits","details":"An infernal duke is a powerful devil that has not yet made the full transition from unique devil to full archdevil. It possesses several traits, as summarized here. • Immunity to charm and compulsion effects, death effects, fire, and poison. • Resistance to acid 30 and cold 30. • Telepathy 300 ft. • Lorthact's natural weapons, as well as any weapon he wields, are treated as evil and lawful for the purpose of overcoming damage reduction. • Lorthact can grant spells to his worshipers. Granting spells doesn't require any specific action on his behalf. Lorthact grants access to the domains of Evil, Law, Magic, and Trickery. His favored weapon is the quarterstaff."},{"type":"Intelligence Drain","kind":"Su","details":"Lorthact drains 1 point of Intelligence each time he hits with a weapon or natural weapon (Will DC 39 negates). Alternatively, he can make a single melee touch attack per round, dealing no hit point damage but draining 2d4 points of Intelligence (Will DC 39 half). After draining Intelligence from a creature, Lorthact gains the benefit of foresight (as the spell) against that creature for 1 minute."},{"type":"Scholastic Masquerade","kind":"Su","details":"When targeting a dominated wizard with his spell reservoir ability, Lorthact can also steal a school power from that wizard's chosen school. He can steal one of the wizard's 1st-level school powers by using three levels of his spell reservoir, both 1st-level school powers at a cost of six levels, and all school powers at a cost of nine levels. While Lorthact retains these powers, the target wizard cannot use them. The stolen powers function at the target wizard's level. Lorthact can steal school powers or a prepared spell from a dominated wizard, but not both. He may steal school powers from multiple schools if he has multiple wizards dominated."},{"type":"Spell Reservoir","kind":"Su","details":"Lorthact can drain prepared arcane spells from the mind of a creature he has dominated and store them for later use, similarly to a ring of spell storing. Draining a spell requires 1 full-round action if he is able to touch the target, or 1 minute to perform through the mental link provided by the dominate effect; in either case, no saving throw is allowed. He can hold no more than one stolen spell from each dominated caster in his spell reservoir, and the total level of stolen spells cannot exceed 25. These stolen spells take effect at the original caster's level."},{"type":"Temporal Anomaly","kind":"Su","details":"Lorthact exists slightly outside of the normal timestream. Spells that predict the future-such as augury, divination, foresight, and moment of prescience—cannot perceive him and provide no benefit against him or information about him. In addition, whenever a creature within 60 ft. of him uses time stop, Lorthact can act normally within the duration of the time stop, as if he had cast it himself. As neither Lorthact nor the caster are frozen in time with respect to each other, each can target and affect the other with attacks, spells, or other effects they create, though they cannot affect other creatures within the duration of the time stop. This ability functions even if Lorthact is flat-footed or unaware of his opponent."}],"description":"Lorthact the Unraveler, also named the Dwimmerlaik, the Ur-Magius, and the Diabolus Mystere, was once a high-ranking duke of Hell. Atypically, he was not solely bound to the service of a single archdevil, instead serving openly at various times as a mystical advisor and consultant on magical matters under both Geryon and Mephistopheles. Some believed him to be secretly a favorite of Asmodeus himself; this supposed favor provided some measure of protection from his jealous rivals. His last mistress in Hell was Eiseth, Whore-Queen of the erinyes, but when Eiseth uncovered a plot to reverse their positions-Lorthact arrogating himself to lordship and reducing her to mere consort-her wrath was enormous and eternal. Lorthact's allies deserted him lest they taste the fury of the erinyes. Lorthact proclaimed his innocence, but he saw condemnation awaiting and fled, racing across the planes with the whips of the erinyes at his heels.\n\nAfter several planar refuges proved no shelter from his relentless pursuers, Lorthact sought solace in the mortal realms. Laying several false leads, he then doubled back to the diabolists of Cheliax, the first place his pursuers looked for him on Golarion. But after they had moved on, he slipped back into places they thought already thoroughly scoured. Adopting a succession of guises, he kept his presence hidden for years, but he never felt truly comfortable under the gaze of so many potentially unfriendly eyes. Seeking a more remote locale, he traveled to the farthest reaches of Chelish sovereignty: the Varisian city-state of Korvosa. There he found the perfect patsy in the vain and corrupt Lord Volshyenek Ornelos. Rebuffed by House Thrune in his quest to restore his youth and vigor, Volshyenek was easy prey for Lorthact's inveigling. The devil bound him in a web of lies and stole not only his soul but also his life. Impersonating Lord Ornelos for over 200 years, he became a dominant figure in Korvosa, shadow-master of the Acadamae and sire of a great house. Meanwhile, he sought ways to rebuild his diabolic power and his store of souls so one day he might buy his way back to ducal favor in Hell.\n\nIn the end, Eiseth's diabolic assassins found him at long last, and he was forced to fake his own death. Yet he still dominates Korvosa from the shadows, controlling the Acadamae through his descendant Toff Ornelos. Little happens in the city without his knowledge, and he plays the part of the mage through shadow-magic, illusions, limited wishes, and the stolen magic of others. However, casters who delve too deeply into his or Korvosa's secrets find themselves at odds with the deadly duke, his powers honed by centuries of exile to undermine and destroy mages who might uncover his identity or unravel his schemes.","ecology":"","habitat_society":"","gear":"boots of speed, rods of cancellation (2), staff of power, bracers of armor +6, mirror of life trapping, ring of evasion, ring of protection +5"},{"name":"Mythic Wyrm Red Dragon","cr":25,"xp":1638400,"alignment":"CE","size":"Gargantuan","type":"dragon","subtypes":["fire","mythic"],"init":12,"init_special":"mythic","senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"smoke vision"},{"type":"x-ray vision"}],"auras":["fire (10 ft., 2d6 fire)","frightful presence (330 ft., DC 30)"],"ac":50,"ac_touch":4,"ac_flat_footed":50,"ac_mods":"-2 Dex, +46 natural, -4 size","hp":518,"hd":"27d12+343","hdvalue":27,"hp_mods":["fast healing 5"],"fort":24,"ref":13,"will":22,"defensive_abilities":["dragon blood (2d6 fire)","fortification (50%)"],"dr":"20/epic and magic","immunities":["dragon traits","fire","paralysis","sleep"],"sr":36,"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":250,"maneuverability":"clumsy"}],"melee":"bite +40 (4d6+25/18-20 plus bleed and grab), 2 claws +40 (2d8+17/19-20 plus bleed and grab), 2 wings +38 (2d6+8), tail slap +38 (2d8+25)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"bleed","details":"2d6"},{"type":"breath weapon","details":"60-ft. cone, 22d10 fire damage, Reflex DC 32 half, usable every 1d4 rounds"},{"type":"crush"},{"type":"dragon fury","details":"2d6 fire"},{"type":"lingering breath","details":"4d6 fire, 10 rounds"},{"type":"manipulate flames"},{"type":"melt stone"},{"type":"mythic power","details":"10/day, surge +1d12"},{"type":"sooty flame"},{"type":"swallow whole","details":"2d6 bludgeoning and 2d6 fire damage, AC 28, 51 hp"},{"type":"tail sweep","details":"DC 32, 2d6+25"},{"type":"wild arcana"}],"spell_like_abilities_caster_level":27,"spell_like_abilities_concentration":36,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"find the path"},{"spell":"pyrotechnics"},{"spell":"suggestion"},{"spell":"wall of fire"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":17,"spellsknown_concentration":26,"spellsknown":[{"spell_level":8,"spell_slots":4,"spells":[{"spell":"discern location"},{"spell":"iron body"}]},{"spell_level":7,"spell_slots":7,"spells":[{"spell":"insanity"},{"spell":"mythic limited wish"},{"spell":"spell turning"}]},{"spell_level":6,"spell_slots":7,"spells":[{"spell":"mythic antimagic field"},{"spell":"mythic contingency"},{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"polymorph"},{"spell":"telekinesis"},{"spell":"teleport"},{"spell":"mythic wall of force"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"fear"},{"spell":"fire shield"},{"spell":"greater invisibility"},{"spell":"mythic stoneskin"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"mythic dispel magic"},{"spell":"displacement"},{"spell":"mythic haste"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"alter self"},{"spell":"detect thoughts"},{"spell":"misdirection"},{"spell":"mythic resist energy"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"alarm"},{"spell":"grease"},{"spell":"mythic magic missile"},{"spell":"shield"},{"spell":"mythic true strike"}]}],"strength":45,"dexterity":6,"constitution":29,"intelligence":20,"wisdom":21,"charisma":24,"baseatk":27,"cmb":48,"cmb_special":"+4 vs. grapple","cmd":56,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Critical Focus","type":"mythic"},{"feat":"Greater Vital Strike"},{"feat":"Improved Critical (bite)","type":"mythic"},{"feat":"Improved Critical (claws)"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will","type":"mythic"},{"feat":"Multiattack"},{"feat":"Power Attack","type":"mythic"},{"feat":"Quicken Spell"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Appraise","value":35},{"skill":"Bluff","value":37},{"skill":"Diplomacy","value":37},{"skill":"Fly","value":14},{"skill":"Intimidate","value":37},{"skill":"Knowledge (arcana)","value":35},{"skill":"Knowledge (history)","value":35},{"skill":"Perception","value":35},{"skill":"Sense Motive","value":35},{"skill":"Spellcraft","value":35},{"skill":"Stealth","value":16}],"languages":["Abyssal","Common","Draconic","Dwarven","Giant","Orc"],"sq":[{"type":"dragon cantrips"},{"type":"mythic spellcasting"}],"environments":["warm mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"A ruddy glow emanates from beneath this dragon's red, gem-encrusted scales, like lava visible between cracks of cooling stone.","group":"Red","source":"Mythic Adventures","special_abilities":[{"type":"Fire Aura","kind":"Su","details":"A wyrm red dragon is surrounded by an aura of intense heat. All creatures within 10 ft. take 2d6 points of fire damage at the beginning of the dragon's turn."},{"type":"Manipulate Flames","kind":"Su","details":"A wyrm red dragon can control any fire spell within 110 ft. of the dragon as a standard action. This ability allows it to move any fire effect in the area, as if it were the caster. This ability also allows it to reposition a stationary fire effect, although the new placement must be one allowed by the spell. Finally, for 1 round following the use of this ability, the dragon can control any new fire spell cast within its area of control, as if it were the caster. It can make all decisions allowed to the caster, including canceling the spell if it so desires."},{"type":"Melt Stone","kind":"Su","details":"The dragon can use its breath weapon to melt rock at a range of 100 ft., affecting a 55-foot-radius area. The area becomes lava to a depth of 1 foot. Any creature in contact with the lava takes 20d6 points of fire damage on the first round, 10d6 on the second, and none thereafter as the lava hardens and cools. If used on a wall or ceiling, treat this ability as an avalanche that deals fire damage."}],"description":"Few creatures inspire such dread as the magnificently wrathful red dragons, and the ones with mythic power are even more fearful. They are the embodiments of destruction, hatred, and draconic arrogance. Magnificent and utterly frightening to behold, mythic red dragons possess a fierce beauty that exceeds all other dragons. From their powerful jaws, capable of snapping iron bars and the masts of ships, to their muscular tails, which can crash through stone walls as easily as whips break skin, red dragons reflect predatory superiority and murderous perfection. A mythic red dragon's body has cordlike muscles that allow it to move more quickly and gracefully than a creature of its size should have a right to.\n\nVillains of the worst kind, mythic red dragons are unf linchingly evil in ways rarely matched even by other mythic evil creatures.\n\nTheir destructive impulses and wrathful fiery rampages surprise and delight the most heinous demons. These legendary dragons demand annual royal sacrifices or tribute in slaves, and think nothing of working their underlings to death.\n\nAn older mythic red dragon spends little time out of its lair, and when it does emerge it prefers to attack humanoid settlements away from the immediate vicinity, burning down buildings, dropping peasants from great heights, and demanding coins and other treasures. This raiding pattern makes it difficult for would-be dragonslayers to find the creature's actual lair.\n\nMythic red dragons use their magic to protect their lairs with a variety of protective spells. A typical lair also contains slave-built mundane traps, environmental hazards such as steam vents poisonous fumes, and (if within an active volcano) molten rock as part of its defenses.","ecology":"","habitat_society":""}];
